INSERT INTO leyes (id,titulo,siglas,tipo,fecha_publicacion,fecha_ultima_reforma,vigente,url_original,temas_clave) VALUES ('e8aebfb8-d776-59d6-978f-623e4fb3e6af','Acuerdo de la Comisión Nacional de Energía por el que se expiden las Disposiciones Administrativas de Carácter General que regulan la actividad de comercialización de gas natural, petrolíferos, gas licuado de petróleo y petroquímicos.','DACG-COMERCIALIZACION-CNE','dacg','2026-11-05',NULL,NULL,'https://dof.gob.mx/nota_detalle.php?codigo=5803022&fecha=05/11/2026',ARRAY['CNE','Comercialización','Hidrocarburos','Petrolíferos']);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('b2082b6d-315b-5312-b73b-fcb977604412','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Preámbulo y considerandos','<h1> ACUERDO de la Comisión Nacional de Energía por el que se expiden las Disposiciones Administrativas de Carácter General que regulan la actividad de comercialización de gas natural, petrolíferos, gas licuado de petróleo y petroquímicos.</h1>
<h2> Al margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos.- Comisión Nacional de Energía.</h2>
<p> JUAN CARLOS SOLÍS ÁVILA, Director General de la Comisión Nacional de Energía, con fundamento en los artículos 25, último párrafo, 28, noveno párrafo, y 90, primer párrafo de la Constitución Política de los Estados Unidos Mexicanos; 1, 2, fracción I, 17, 26, fracción IX, y 33, último párrafo de la Ley Orgánica de la Administración Pública Federal; 1, primer párrafo, 2, 3, 4 y 13 de la Ley Federal de Procedimiento Administrativo; 1, 2, 3, fracción XXXIV, 5, 6 y 24, fracciones I y V de la Ley Nacional para Eliminar Trámites Burocráticos; 1, 2, primer párrafo, 3, 7, fracciones I, II, III, V y VI, 9, fracciones II, III y IV, 16, fracciones I, VI, VII, X, XIX y XXI, 17, fracciones I, II, III y IV de la Ley de la Comisión Nacional de Energía; 1, 3, fracciones III, IV y V, 5, fracciones XII, XXII, XXIII, XXXVII, XXXVIII, XL y XLIX, 9, 76, fracción II, 80, 81, 82, fracciones I y V, 86, 87, 88, 89, 116, fracciones I y V, 117, 119, 121, fracción II, 123, 127, 152,153 y 166 de la Ley del Sector Hidrocarburos; 2, 5, 85, 91, 93, 95, 96, 106, 107, 108, 109, 142, primer y último párrafos, 143, 146, 153, 154, 155, 156, 157, 158, 160, 161, 173, 200, 331 y Transitorio Vigésimo del Reglamento de la Ley del Sector Hidrocarburos; 2, apartado F, fracción III, 71, 77 y 78 del Reglamento Interior de la Secretaría de Energía; 2, 7, 9, 10, 12, fracciones I, II, IX y XI, y 19, del Reglamento Interior de la Comisión Nacional de Energía; 7, fracción II, del Acuerdo CT/1.SE/2-2025, Aprobación de las Reglas de Operación del Comité Técnico de la Comisión Nacional de Energía, así como el Acuerdo número CT/20.SO/40-2026, emitido por el Comité Técnico de la Comisión Nacional de Energía, y</p>
<p> CONSIDERANDO<br/> </p>
<p> Que el artículo 25, último párrafo, de la Constitución Política de los Estados Unidos Mexicanos establece que las autoridades de los tres órdenes de gobierno deben implementar políticas públicas de simplificación administrativa y digitalización de trámites y servicios, buenas prácticas regulatorias, desarrollo y fortalecimiento de capacidades tecnológicas públicas y demás objetivos que establezca la ley nacional en la materia.</p>
<p> Que el artículo 28, noveno párrafo, de la Constitución Política de los Estados Unidos Mexicanos establece que el Poder Ejecutivo Federal, por conducto de la dependencia encargada de conducir y supervisar la política energética del país, cuenta con atribuciones para llevar a cabo la regulación técnica y económica; así como la facultad sancionadora en materia energética y de hidrocarburos.</p>
<p> Que el 18 de marzo de 2025, en cumplimiento al Decreto por el que se reforman, adicionan y derogan diversas disposiciones de la Constitución Política de los Estados Unidos Mexicanos, en materia de simplificación orgánica, publicado en el Diario Oficial de la Federación el 20 de diciembre de 2024, fue emitido en el mismo medio de difusión, el decreto por el que se reforman, adicionan y derogan diversas disposiciones y se expiden, entre otras leyes, la Ley del Sector Hidrocarburos, así como la Ley de la Comisión Nacional de Energía, a partir de la cual se extingue la Comisión Reguladora de Energía y se crea la Comisión Nacional  de Energía.</p>
<p> Que de conformidad con los artículos 2, primer párrafo de la Ley de la Comisión Nacional de Energía y 2, primer párrafo del Reglamento Interior de la Comisión Nacional de Energía, la Comisión Nacional de Energía es un órgano administrativo desconcentrado de carácter técnico, sectorizado a la Secretaría de Energía, que cuenta con independencia técnica, operativa, de gestión y de decisión en los términos de dicha Ley.</p>
<p> Que conforme al artículo 7, fracciones I, II, III y V, de la Ley de la Comisión Nacional de Energía, corresponde a la Comisión Nacional de Energía emitir regulación y disposiciones administrativas de carácter general, supervisar su cumplimiento, así como emitir resoluciones, acuerdos y demás actos administrativos necesarios para el ejercicio de sus atribuciones.</p>
<p> Que la Ley de la Comisión Nacional de Energía, en su artículo 9, fracciones II, III y IV faculta a la Comisión Nacional de Energía para otorgar, modificar, terminar y supervisar, entre otras actividades, los permisos de comercialización de gas natural, petrolíferos y petroquímicos.</p>
<p> Que el artículo 5, fracción XII de la Ley del Sector Hidrocarburos define la comercialización como la actividad de ofertar en territorio nacional a personas permisionarias, usuarias o usuarias finales la compraventa de hidrocarburos, petrolíferos o petroquímicos, la cual puede incluir la gestión o contratación de servicios de transporte, almacenamiento o distribución de dichos productos, así como servicios de valor agregado en beneficio de las personas permisionarias, usuarias o usuarias finales.</p>
<p> Que, de conformidad con lo dispuesto en los artículos 76, fracción II y 116, fracción I de la Ley del Sector Hidrocarburos, corresponde a la Comisión Nacional de Energía, con base en los criterios vinculantes de planeación incorporados en la política pública, regular y supervisar, así como otorgar, modificar, actualizar, suspender y revocar los permisos para las actividades de, entre otras, procesamiento de gas natural y comercialización de gas natural, petrolíferos, gas licuado de petróleo y petroquímicos.</p>
<p> Que el 3 de octubre de 2025, se publicó en el Diario Oficial de la Federación el Reglamento de la Ley del Sector Hidrocarburos, que en sus artículos 5, 91 y 142, primer y último párrafos, dispone que las personas interesadas en obtener los permisos que refiere la Ley del Sector Hidrocarburos deben presentar sus solicitudes ante la Comisión Nacional de Energía, con los requisitos previstos en dicha Ley, su Reglamento y la demás normatividad aplicable, bajo los formatos y especificaciones que para cada actividad permisionada publique la Comisión Nacional de Energía.</p>
<p> Que los artículos 80 de la Ley del Sector Hidrocarburos, así como 96 y 108 del Reglamento de la Ley del Sector Hidrocarburos, establecen los requisitos para que las personas interesadas presenten sus solicitudes de permiso para la realización de la actividad de comercialización de gas natural, petrolíferos o petroquímicos, y que dichas solicitudes deben presentarse en los formatos autorizados para tal efecto.</p>
<p> Que el artículo 82, fracciones I, II y III, de la Ley del Sector Hidrocarburos, establece que los permisos de comercialización deben contener al menos las actividades y obligaciones consistentes en la adquisición y venta de los hidrocarburos, petrolíferos y petroquímicos; contratar para sí mismo o gestionar para las personas permisionarias a quienes realicen la comercialización de hidrocarburos, petrolíferos y petroquímicos, los servicios de transporte, almacenamiento y distribución por medio de ductos que, en su caso, requiera para la realización de sus actividades.</p>
<p> Que el artículo 119, fracción II, de la Ley del Sector Hidrocarburos, establece que las personas permisionarias de las actividades reguladas por la Comisión Nacional de Energía deben cumplir con los términos y condiciones establecidos en los permisos, así como abstenerse de ceder, traspasar, realizar compra venta o gravar, total o parcialmente, los derechos u obligaciones derivados de los mismos en contravención de la Ley del Sector Hidrocarburos.</p>
<p> Que el artículo 90 del Reglamento de la Ley del Sector Hidrocarburos señala que un particular o las empresas públicas del Estado, pueden ser titulares de forma directa o indirecta a través de filiales o partes relacionadas, de distintos permisos a los que refiere la Ley del Sector Hidrocarburos, de lo que se desprende que la Ley del Sector Hidrocarburos y el Reglamento de la Ley del Sector Hidrocarburos no contienen disposiciones que prohíban a quienes realizan actividades de exploración y extracción y refinación de petróleo, procesamiento de gas natural o formulación, obtener un permiso de comercialización respecto de los productos obtenidos directamente de sus actividades autorizadas.</p>
<p> Que el artículo 95 del Reglamento de la Ley del Sector Hidrocarburos dispone que la Comisión Nacional de Energía puede establecer las modalidades de los permisos, así como determinar los petrolíferos y petroquímicos que deban estar sujetos a regulación en la normatividad que para tal efecto emita.</p>
<p> Que el artículo 107 del citado Reglamento, establece que en la normatividad que emita la Comisión Nacional de Energía se pueden establecer limitaciones a las operaciones que se realicen entre las personas permisionarias de comercialización, así como la forma en que deben prestar sus servicios a otras personas usuarias que también sean titulares de un permiso de comercialización.</p>
<p> Que el artículo 108, fracción III y segundo párrafo del Reglamento de la Ley del Sector Hidrocarburos establece como un requisito para la solicitud de los permisos de comercialización, la entrega de las cartas de intención o equivalente de compra suscritas con cada uno de sus potenciales proveedores, en las que se exprese el volumen ofertado de compra de hidrocarburos, petrolíferos o petroquímicos, y en caso de que resulte procedente el otorgamiento del permiso, se establece como una condición suspensiva para su emisión la presentación de los contratos formalizados que deriven de las cartas de intención o equivalentes de compra antes señaladas.</p>
<p> Que el artículo 143 del Reglamento de la Ley del Sector Hidrocarburos establece el procedimiento para evaluar las solicitudes de permiso, incluyendo las etapas de admisión a trámite, prevención y resolución, mientras el artículo 93 del mismo Reglamento establece los criterios técnicos, económicos y regulatorios para la determinación de las vigencias correspondientes a las actividades reguladas.</p>
<p> Que, conforme a lo previsto en el artículo 331 del Reglamento de la Ley del Sector Hidrocarburos, la Comisión Nacional de Energía no debe otorgar, modificar o ceder un permiso cuando la persona solicitante se ubique en los supuestos determinados en dicho artículo, así como los demás que se prevean en la normatividad aplicable.</p>
<p> Que, derivado de lo anterior, resulta relevante que la Comisión Nacional de Energía emita las presentes disposiciones administrativas de carácter general para establecer en un solo instrumento los diversos aspectos que se prevén en la Ley del Sector Hidrocarburos y el Reglamento de la Ley del Sector Hidrocarburos sobre la actividad de comercialización de gas natural, petrolíferos, gas licuado de petróleo y petroquímicos, en beneficio de los distintos participantes del sector hidrocarburos.</p>
<p> Que, las actividades de exploración y extracción, procesamiento de gas natural, formulación y refinación de petróleo propician el desarrollo de infraestructura para aumentar la producción nacional de gas natural, petrolíferos y petroquímicos, por lo que requieren inversiones de mediano y largo plazo. En ese sentido, es a través de un permiso de comercialización que las personas que lleven a cabo estas actividades pueden colocar los productos en el mercado que resulten de su proceso productivo.</p>
<p> Que, de una interpretación sistemática y funcional de la Ley del Sector Hidrocarburos y del Reglamento de la Ley del Sector Hidrocarburos se concluye que la colocación en el mercado de productos obtenidos directamente de actividades productivas constituye una manifestación material de la actividad de comercialización, toda vez que implica la oferta y compraventa de dichos productos dentro de la cadena regulada de suministro.</p>
<p> Que, la participación directa de los productores de gas natural, petrolíferos y petroquímicos en la comercialización de los productos derivados de su propia actividad productiva contribuye a la eficiencia operativa de los mercados, reduce costos de intermediación, favorece la continuidad de suministro y promueve un aprovechamiento más eficiente de la infraestructura asociada a las actividades reguladas del sector hidrocarburos.</p>
<p> Que los artículos 82, fracción V de la Ley del Sector Hidrocarburos, así como 109, fracciones I, III, IV, V y VI y sexto párrafo del Reglamento de la Ley del Sector Hidrocarburos, establecen que las personas permisionarias de comercialización deben entregar la información que la Comisión Nacional de Energía requiera para fines de supervisión y estadísticos, así como remitir los contratos que acrediten la gestión de servicios de transporte, almacenamiento y distribución por medio de ductos, el inventario y la procedencia lícita de los productos, actualizar la relación de proveedores y clientes, y mantener el padrón de proveedores y clientes finales con los contratos vigentes, los volúmenes comprometidos y el destino final del producto.</p>
<p> Que el artículo 107, último párrafo del Reglamento de la Ley del Sector Hidrocarburos dispone que la marca comercial del producto debe notificarse por cada contrato de servicio y declararse en cada transacción derivada de este, con el propósito de brindar mayor trazabilidad en la cadena de suministro; y que la información de los contratos permite a la Comisión Nacional de Energía conocer la estructura e integración de los mercados, la infraestructura, la logística y la comercialización, así como identificar restricciones a su desarrollo eficiente, a fin de fomentar y promover la competencia en el sector.</p>
<p> Que, de conformidad con el artículo 24, fracciones I y V de la Ley Nacional para Eliminar Trámites Burocráticos y con el fin de reducir la carga administrativa de las personas permisionarias, mediante las presentes disposiciones se habilita un formulario electrónico único, en la Oficialía de Partes Electrónica de la Comisión Nacional de Energía, para el registro, la validación, la modificación y la finalización de los contratos. A través de dicho formulario se dará cumplimiento a la remisión trimestral de la información prevista en el artículo 109, fracciones I, III, IV, V y sexto párrafo del Reglamento de la Ley del Sector Hidrocarburos.</p>
<p> Que, en la Vigésima Sesión Ordinaria, celebrada el 27 de octubre de 2026, el Comité Técnico de la Comisión Nacional de Energía aprobó el Acuerdo CT/20.SO/40-2026, mediante el cual se autoriza la emisión del presente instrumento.</p>
<p> Que en el ejercicio de las facultades conferidas por la normatividad aplicable y en apego a los objetivos y principios señalados en las consideraciones anteriores, con la finalidad de brindar certeza respecto de la actividad de comercialización de gas natural, petrolíferos, gas licuado de petróleo y petroquímicos, así como coadyuvar con los objetivos de la política energética, la simplificación administrativa, la digitalización de trámites y servicios y las buenas prácticas regulatorias, se expide el siguiente:</p>
<p> ACUERDO DE LA COMISIÓN NACIONAL DE ENERGÍA POR EL QUE SE EXPIDEN LAS DISPOSICIONES<br/> ADMINISTRATIVAS DE CARÁCTER GENERAL QUE REGULAN LA ACTIVIDAD DE COMERCIALIZACIÓN DE GAS<br/> NATURAL, PETROLÍFEROS, GAS LICUADO DE PETRÓLEO Y PETROQUÍMICOS<br/> </p>',1,'preambulo','DACG de comercialización','Acuerdo',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('06781a6f-2851-5f5c-ab8f-1b611991215f','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo único del acuerdo','<p> ÚNICO. La Comisión Nacional de Energía emite las Disposiciones Administrativas de Carácter General que regulan la actividad de Comercialización de Gas Natural, Petrolíferos, Gas Licuado de Petróleo y Petroquímicos, para quedar como sigue:</p>
<p> DISPOSICIONES ADMINISTRATIVAS DE CARÁCTER GENERAL QUE REGULAN LA ACTIVIDAD DE<br/> COMERCIALIZACIÓN DE GAS NATURAL, PETROLÍFEROS, GAS LICUADO DE PETRÓLEO Y PETROQUÍMICOS<br/> </p>',2,'ordinario','DACG de comercialización','Acuerdo',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('e1812a72-3ed2-57b4-b232-3e60f5c7cd55','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 1','<p> CAPÍTULO I<br/> </p>
<p> Disposiciones generales<br/> </p>
<p> Artículo 1. Objetivo. Las presentes Disposiciones tienen por objeto establecer la regulación aplicable a la actividad de Comercialización de Gas Natural, Petrolíferos, Gas Licuado de Petróleo y Petroquímicos por parte de la Comisión Nacional de Energía, considerando lo previsto en la Ley del Sector Hidrocarburos y su Reglamento.</p>',3,'ordinario','DACG de comercialización','CAPÍTULO I · Disposiciones generales',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('210b6c53-db67-5e4c-bd99-18aafaf96944','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 2','<p> Artículo 2. Ámbito de Aplicación. Las presentes Disposiciones son de carácter general y observancia obligatoria en todo el territorio nacional y resultan aplicables a las personas físicas, morales, entidades paraestatales y empresas públicas del Estado que encuadren en alguno de los siguientes supuestos:</p>
<p> I.          Tengan interés en realizar la actividad de Comercialización de Gas Natural, Petrolíferos, Gas Licuado de Petróleo o Petroquímicos;</p>
<p> II.         Cuenten con un permiso vigente de Comercialización de Gas Natural, Petrolíferos, Gas Licuado de Petróleo o Petroquímicos;</p>
<p> III.        Cuenten con algún otro permiso previsto en el artículo 76 de la Ley del Sector Hidrocarburos y que tengan o pretendan tener relaciones comerciales con personas titulares de un permiso vigente de Comercialización de Gas Natural, Petrolíferos, Gas Licuado de Petróleo o Petroquímicos, y</p>
<p> IV.        Sean titulares de una Asignación o Contrato para la Exploración y Extracción; cuenten con un permiso de Procesamiento de Gas Natural, Formulación o Refinación de Petróleo y pretendan comercializar Gas Natural, Petrolíferos, Gas Licuado de Petróleo o Petroquímicos que provengan de sus procesos productivos.</p>',4,'ordinario','DACG de comercialización','CAPÍTULO I · Disposiciones generales',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('5f978b51-4db7-557a-a68b-502451392b99','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 3','<p> Artículo 3. Definiciones. Para efectos de la interpretación y aplicación de estas Disposiciones, además de las definiciones establecidas en la Ley de la Comisión Nacional de Energía, la Ley del Sector Hidrocarburos y su Reglamento, se deben entender, en singular o plural, las siguientes:</p>
<p> I.          CFDI: Comprobante Fiscal Digital por Internet;</p>
<p> II.         ContratoId: Identificador único que el Formulario de Contratos genera de forma automática al completarse el registro de un contrato y que vincula cada transacción con el contrato que la respalda;</p>
<p> III.        Disposiciones: Las presentes Disposiciones Administrativas de Carácter General que regulan la actividad de Comercialización de Gas Natural, Petrolíferos, Gas Licuado de Petróleo y Petroquímicos;</p>
<p> IV.        Formulario de Contratos: Formulario electrónico habilitado por la Comisión en la Oficialía de Partes Electrónica para el registro, la validación, la modificación y la finalización de los contratos a que se refiere el Capítulo XI de las presentes Disposiciones;</p>
<p> V.         Grupo de Interés Económico: Conjunto de personas físicas o morales con intereses comerciales o financieros afines, que coordinan sus actividades para lograr un objetivo común, o entre las que existen acuerdos, de cualquier naturaleza, para tomar decisiones en un mismo sentido, o en el que una o varias de ellas ejercen, directa o indirectamente, el control de las demás;</p>
<p> VI.        Ofertar: Acción de poner a disposición de personas Permisionarias, Usuarias o Usuarias Finales, en territorio nacional, Gas Natural, Petrolíferos, Gas Licuado de Petróleo o Petroquímicos para su compraventa, mediante instrumentos físicos o electrónicos que expresen, al menos, el producto objeto de la oferta, el volumen ofertado, la modalidad y condiciones de venta y entrega, precio de los productos ofertados y demás información que la persona oferente considere, conforme a las buenas prácticas comerciales, que constituyen al acto previo y vinculado a la venta. La simple manifestación de intención, o la difusión de información sin posibilidad real de contratación, no constituyen por sí mismas, una actividad de oferta;</p>
<p> VII.       Oficialía de Partes Electrónica: Herramienta tecnológica instrumentada por medio de un portal de internet que permite a la persona acreditada ante la Comisión realizar trámites, presentar solicitudes, promociones o documentación relacionada con las actividades del sector energético; y a la Comisión, realizar actuaciones, supervisar y practicar notificaciones a la persona acreditada, con relación a dichas actividades reguladas. A la cual se accede mediante la siguiente liga electrónica: https://ope.cne.gob.mx/;</p>
<p> VIII.      Persona solicitante: Persona física, moral, entidad paraestatal o empresa pública del Estado, que presenta ante la Comisión una solicitud para obtener un permiso para la actividad de Comercialización que cumpla con las características establecidas en el artículo 2 de las presentes Disposiciones;</p>
<p> IX.        Reglas Generales: Reglas Generales para el funcionamiento de la Oficialía de Partes Electrónica de la Comisión Nacional de Energía, publicadas en el Diario Oficial de la Federación el 9 de octubre de 2025, o aquellas que las modifiquen o sustituyan;</p>
<p> X.         RFC: Registro Federal de Contribuyentes, y</p>
<p> XI.        Terminación anticipada del Contrato: Acción de terminación del contrato de Comercialización de manera anticipada a la fecha pactada.</p>',5,'ordinario','DACG de comercialización','CAPÍTULO I · Disposiciones generales',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('c7ea3019-0442-55d3-bbb7-2c9f08ca04f9','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 4','<p> CAPÍTULO II<br/> </p>
<p> De la actividad de Comercialización<br/> </p>
<p> Artículo 4. De la Actividad de Comercialización. A efecto de regular el ejercicio de los derechos conferidos en los permisos de Comercialización de Gas Natural, Petrolíferos, Gas Licuado de Petróleo y Petroquímicos a que hacen referencia los artículos 3, fracciones III, IV y V; 5, fracción XII, 76, fracción II, incisos a), b) y c) y 82 de la Ley del Sector Hidrocarburos, la actividad de Comercialización consiste en adquirir, Ofertar y vender estos productos y, en su caso, realizar la gestión o contratación de los servicios de Transporte, Almacenamiento o Distribución de los productos vendidos, así como de servicios de valor agregado, en beneficio de las personas Permisionarias, Usuarias o Usuarias Finales, dentro del territorio nacional.</p>
<p> Lo anterior se entiende sin perjuicio del cumplimiento de las demás obligaciones previstas en los artículos 82 de la Ley del Sector Hidrocarburos y 109 del Reglamento de la Ley del Sector Hidrocarburos, así como las contenidas en el título de permiso correspondiente y demás Normatividad aplicable.</p>',6,'ordinario','DACG de comercialización','CAPÍTULO II · De la actividad de Comercialización',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('15e6477c-2a06-5471-80bf-71212d7c2cd5','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 5','<p> Artículo 5. Del origen y Trazabilidad de los productos a comercializar. Para llevar a cabo la oferta y venta de Gas Natural, Petrolíferos, Gas Licuado de Petróleo y Petroquímicos, las personas Permisionarias de Comercialización deben acreditar el origen y la disponibilidad lícita de los productos que se pretenden comercializar, mediante la documentación que corresponda a su importación, producción o adquisición en territorio nacional, según resulte aplicable.</p>
<p> Para acreditar lo anterior, en términos del artículo 82 de la Ley del Sector Hidrocarburos, así como los artículos 107, 109 y Vigésimo transitorio del Reglamento de la Ley del Sector Hidrocarburos, las personas Permisionarias de Comercialización deben cumplir, según corresponda, con lo siguiente:</p>
<p> I.          En caso de que el producto sea importado directamente del extranjero por la propia persona Permisionaria de Comercialización, esta debe contar con:</p>
<p> a)    Los permisos de importación y Comercialización vigentes que correspondan, conforme a lo previsto en la Ley del Sector Hidrocarburos, el Reglamento de la Ley del Sector Hidrocarburos y demás Normatividad aplicable;</p>
<p> b)    Los contratos o documentos internacionales equivalentes de compra vinculante debidamente suscritos con su proveedor extranjero que amparen la compra de los productos a comercializar.</p>
<p>        Se entienden como documentos internacionales equivalentes de compra los siguientes: contrato de suministro internacional, complemento carta porte, la factura comercial emitida por el proveedor extranjero, contrato marco de compraventa, carta intención, confirmaciones de transacciones o cualquier otro instrumento jurídico o comercial de carácter internacional que resulte equiparable y que permita acreditar de manera fehaciente la legal adquisición de los productos objeto de Comercialización;</p>
<p> c)     Los contratos o documentos equivalentes que amparen la contratación por sí mismo o por parte de sus proveedores de los servicios de Transporte, Almacenamiento y Distribución de los productos a comercializar, ya sea en territorio nacional o en el extranjero, según corresponda y aplique;</p>
<p> d)    Los pedimentos de importación de los productos importados, conforme se prevea en las disposiciones jurídicas que resulten aplicables, y</p>
<p> e)    Los CFDI que amparen las operaciones que correspondan, de conformidad con las disposiciones legales aplicables, que contengan de manera enunciativa mas no limitativa los siguientes elementos:</p>
<p> i.      Identificación del comprobante: versión, fecha y hora de expedición, tipo de comprobante, serie y folio cuando se utilicen, lugar de expedición y datos de certificación;</p>
<p> ii.     Identidad fiscal: datos generales del emisor, tales como el RFC, nombre o razón social y régimen fiscal en que tributen, y del receptor, tales como el RFC, nombre o razón social, código postal del domicilio fiscal, régimen fiscal en que tributen, indicando la clave del uso del CFDI, conforme a las reglas aplicables;</p>
<p> iii.    Conceptos facturados: clave del producto o servicio del catálogo del Servicio de Administración Tributaria, cantidad, clave de unidad, descripción específica del producto, valor unitario, importe y descuentos, cuando correspondan. Para efectos de Trazabilidad, la descripción debe permitir identificar el Petrolífero, el Gas Licuado de Petróleo, el Gas Natural o el Petroquímico objeto de la operación;</p>
<p> iv.    Impuestos: que incluya el monto de los impuestos trasladados desglosados con cada una de las tasas del impuesto correspondiente y, en su caso, el monto de los impuestos retenidos, además debe reflejarse correctamente la situación de los productos que no causen un impuesto o estén sujetos a un tratamiento específico;</p>
<p> v.     Totales: subtotal, descuentos, impuestos trasladados o retenidos y total de la operación, según corresponda;</p>
<p> vi.    Complemento carta porte, según aplique, y</p>
<p> vii.   Los demás elementos de autentificación que sean establecidos por la autoridad fiscal competente conforme a la Normatividad aplicable.</p>
<p> II.         En caso de que el producto sea producido o formulado en territorio nacional por la propia persona Permisionaria de Comercialización, esta debe contar con:</p>
<p> a)    Los permisos de Refinación de Petróleo, Procesamiento de Gas Natural o Formulación según corresponda, o en su caso, con los Títulos de Asignación o Contratos para la Exploración y Extracción, conforme a lo previsto en la Ley del Sector Hidrocarburos, el Reglamento de la Ley del Sector Hidrocarburos y demás Normatividad aplicable;</p>
<p> b)    La documentación que permita identificar y vincular el producto desde su producción o formulación hasta su entrega al adquirente o destinatario en cada una de las etapas de su proceso de comercialización, la cual debe incluir por lo menos el tipo de producto producido o formulado, el volumen producido o formulado, la unidad de medida, en su caso el lote, número de identificación o equivalente, así como la fecha y lugar de producción o formulación.</p>
<p> c)     La documentación que ampare las operaciones realizadas desde su producción o formulación hasta su destino final, que permita establecer la Trazabilidad y correspondencia documental y volumétrica entre el producto producido o formulado y el producto entregado.</p>
<p>        Estos documentos de manera enunciativa mas no limitativa pueden consistir en contratos de suministro, de compraventa o documentos equivalentes, complemento carta porte, pedimentos de importación correspondientes a los insumos o componentes de procedencia extranjera utilizados en su producción o Formulación;</p>
<p> d)    Los CFDI que amparen las operaciones que correspondan, de conformidad con las disposiciones legales aplicables, deben contener de manera enunciativa mas no limitativa los siguientes elementos:</p>
<p> i.      Identificación del comprobante: versión, fecha y hora de expedición, tipo de comprobante, serie y folio cuando se utilicen, lugar de expedición y datos de certificación;</p>
<p> ii.     Identidad fiscal: datos generales del emisor, tales como el RFC, nombre o razón social y régimen fiscal en que tributen, y del receptor, tales como el RFC, nombre o razón social, código postal del domicilio fiscal, régimen fiscal en que tributen, indicando la clave del uso del CFDI, conforme a las reglas aplicables;</p>
<p> iii.    Conceptos facturados: clave del producto o servicio del catálogo del Servicio de Administración Tributaria, cantidad, clave de unidad, descripción específica del producto, valor unitario, importe y descuentos, cuando correspondan. Para efectos de Trazabilidad, la descripción debe permitir identificar el Petrolífero, el Gas Licuado de Petróleo, el Gas Natural o el Petroquímico objeto de la operación;</p>
<p> iv.    Impuestos: que incluya el monto de los impuestos trasladados desglosados con cada una de las tasas del impuesto correspondiente y, en su caso, el monto de los impuestos retenidos; además debe reflejarse correctamente la situación de los productos que no causen un impuesto o estén sujetos a un tratamiento específico;</p>
<p> v.     Totales: subtotal, descuentos, impuestos trasladados o retenidos y total de la operación, según corresponda;</p>
<p> vi.    Complemento carta porte, según aplique, y</p>
<p> vii.   Los demás elementos de autentificación que sean establecidos por la autoridad fiscal competente conforme a la Normatividad aplicable.</p>
<p>             La información contenida en dichos comprobantes debe ser coincidente respecto del tipo de producto, volumen y unidad de medida, que permita identificar la procedencia del producto, así como acreditar su correspondencia con las entradas, salidas, existencias, transferencias, mermas y demás variaciones operativas que, en su caso, se hubieren generado desde su producción o formulación hasta su entrega al adquirente o destinatario;</p>
<p> III.        En caso de que el producto sea adquirido en territorio nacional, de conformidad con el artículo 82, fracción I de la Ley del Sector Hidrocarburos, este debe provenir de otra persona Permisionaria de Comercialización que, a su vez, puede ser Permisionaria de Refinación de Petróleo, Procesamiento de Gas Natural, Formulación o importación, según aplique, para lo cual, deben contar con:</p>
<p> a)    Los permisos de Comercialización, Refinación de Petróleo, Procesamiento de Gas Natural, Formulación o importación, según corresponda, conforme a lo previsto en la Ley del Sector Hidrocarburos, el Reglamento de la Ley del Sector Hidrocarburos y demás Normatividad aplicable;</p>
<p> b)    Los contratos de compra vinculante debidamente suscritos, entre los que se encuentran la factura comercial, contrato de compraventa, carta intención o cualquier otro instrumento jurídico o comercial que resulte equiparable y que permita acreditar de manera fehaciente la adquisición de los productos objeto de Comercialización;</p>
<p> c)     Los CFDI que amparen las operaciones que correspondan, de conformidad con las disposiciones legales aplicables, deben contener de manera enunciativa mas no limitativa los siguientes elementos:</p>
<p> i.      Identificación del comprobante: versión, fecha y hora de expedición, tipo de comprobante, serie y folio cuando se utilicen, lugar de expedición y datos de certificación;</p>
<p> ii.     Identidad fiscal: datos generales del emisor, tales como RFC, nombre o razón social y régimen fiscal en que tributen, y del receptor, tales como RFC, nombre o razón social, código postal del domicilio fiscal, régimen fiscal en que tributen, indicando la clave del uso del CFDI, conforme a las reglas aplicables;</p>
<p> iii.    Conceptos facturados: clave del producto o servicio del catálogo del Servicio de Administración Tributaria, cantidad, clave de unidad, descripción específica del producto, valor unitario, importe y descuentos, cuando correspondan. Para efectos de Trazabilidad, la descripción debe permitir identificar el Petrolífero, el Gas Licuado de Petróleo, el Gas Natural o el Petroquímico objeto de la operación;</p>
<p> iv.    Impuestos: que incluya el monto de los impuestos trasladados desglosados con cada una de las tasas del impuesto correspondiente y, en su caso, el monto de los impuestos retenidos; además debe reflejarse correctamente la situación de los productos que no causen un impuesto o estén sujetos a un tratamiento específico;</p>
<p> v.     Totales: subtotal, descuentos, impuestos trasladados o retenidos y total de la operación, según corresponda;</p>
<p> vi.    Complemento carta porte, según aplique, y</p>
<p> vii.   Los demás elementos de autentificación que sean establecidos por la autoridad fiscal competente conforme a la Normatividad aplicable.</p>
<p>             Las personas Permisionarias de Comercialización no pueden adquirir Gas Natural, Petrolíferos o Gas Licuado de Petróleo de personas titulares de permisos de Distribución, toda vez que no se encuentra considerado en lo previsto en el artículo 83, fracción II de la Ley del Sector Hidrocarburos.</p>
<p>             La información contenida en dichos comprobantes debe permitir identificar el tipo de producto, el volumen y su unidad de medida, así como acreditar su procedencia y Trazabilidad desde su producción o formulación hasta su entrega al adquirente o destinatario. Para tal efecto, dicha información debe relacionarse con las entradas, salidas, existencias, transferencias, mermas y demás variaciones operativas que correspondan, considerando los registros de medición de los agentes que intervengan en la operación y las diferencias que, en su caso, deriven de la utilización de los diversos sistemas de medición existentes en sus procesos de producción o formulación, y</p>
<p> IV.        En los casos en que las personas titulares de permisos de Comercialización pretendan prestar el servicio a otras personas Usuarias que también sean titulares de un permiso de Comercialización, además de lo señalado en la fracción anterior, deben presentar la documentación que acredite la prestación, gestión o contratación de los servicios de Transporte, Almacenamiento o Distribución, como parte del servicio de Comercialización, acorde con lo previsto en el artículo 107 del Reglamento de la Ley del Sector Hidrocarburos.</p>
<p>             Para realizar la prestación, gestión o contratación de los servicios de Transporte, Almacenamiento o Distribución previstos en el párrafo anterior, la persona Permisionaria de Comercialización de Petrolíferos y Gas Licuado de Petróleo debe ser titular al menos de uno de los permisos asociados a las actividades antes señaladas. En tanto que la persona Permisionaria de Comercialización de Gas Natural debe ser titular de al menos uno de los siguientes permisos: Procesamiento, Compresión, Licuefacción, Descompresión, Regasificación, Transporte por medios distintos a Ducto o Distribución por medios distintos a Ductos de Gas Natural. Lo anterior, sin perjuicio de las excepciones previstas en el Reglamento de la Ley del Sector Hidrocarburos.</p>
<p>             Asimismo, esta fracción resulta aplicable a las personas titulares de permisos de Comercialización que a su vez sean titulares de permisos de importación que pretendan prestar el servicio a otras personas Usuarias que también sean titulares de un permiso de Comercialización.</p>
<p>             La información contenida en dicha documentación debe ser coincidente respecto del tipo de producto, volumen y unidad de medida, así como con la capacidad y unidades aprobadas en los permisos que correspondan; que permita identificar la procedencia del producto, así como acreditar su correspondencia con las entradas, salidas, existencias, transferencias, mermas y demás variaciones operativas que, en su caso, se hubieren generado desde su adquisición hasta su entrega al adquirente o destinatario.</p>
<p> Tratándose de Gas Natural transportado por medio de Ductos, en cualquiera de los supuestos de las fracciones I a IV de este artículo, la Trazabilidad se acredita mediante los balances de volumen o energía por punto de internación, inyección y entrega, con base en la información emitida por las personas Permisionarias de Transporte o Almacenamiento, sin que se requiera la identificación por lote. Para acreditar que la información sea coincidente con los CFDI referidos en las fracciones I, II y III se debe considerar el gas combustible, las mermas, los desbalances y las diferencias de medición reconocidos en la Normatividad aplicable y en los contratos de servicio.</p>
<p> En cualquier momento, la Comisión puede requerir la información y documentación que permita acreditar el cumplimiento de lo previsto en el presente artículo. Por lo que las personas Permisionarias de Comercialización deben asegurarse de que la información y documentación que ampare sus operaciones de comercialización se encuentre actualizada y sea congruente con las actividades y servicios que prestan, así como con los volúmenes y el tipo de productos que comercializan.</p>',7,'ordinario','DACG de comercialización','CAPÍTULO II · De la actividad de Comercialización',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('23f979d5-d765-56b7-8954-36aeb7d46ee2','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 6','<p> Artículo 6. Materialidad de la oferta. La persona Permisionaria de Comercialización para realizar la oferta, debe acreditar ante la Comisión cuando así lo requiera, al menos los siguientes elementos:</p>
<p> I.          La existencia de canales activos, tales como: la promoción, difusión o contratación de los productos y servicios ofertados de la actividad de Comercialización, los cuales pueden acreditarse mediante plataformas digitales, medios de publicidad del comercializador y canales de contacto comercial, señalando el portal vigente donde se publiquen;</p>
<p> II.         Las condiciones comerciales, incluido el precio o su fórmula, contenidas en los instrumentos de oferta dirigidos a sus clientes potenciales;</p>
<p> III.        La disponibilidad operativa, técnica, financiera y jurídica para suministrar el bien o prestar el servicio ofertado;</p>
<p> IV.        La asignación de personal, plataformas tecnológicas o recursos materiales destinados a soportar la actividad ofertada;</p>
<p> V.         La información necesaria para que los clientes potenciales puedan contratar o acceder a la oferta;</p>
<p> VI.        Los registros contables, comerciales, operativos o documentales asociados a la actividad ofertada, y</p>
<p> VII.       Cualquier otro elemento que permita acreditar que la oferta corresponde a una actividad económica lícita.</p>
<p> La Comisión para los efectos conducentes debe considerar que no existe una actividad efectiva de Ofertar cuando la persona Permisionaria de Comercialización no acredite la realización de los actos señalados en fracciones anteriores de Comercialización o puesta a disposición del bien o servicio durante un periodo continuo de ciento ochenta días naturales.</p>',8,'ordinario','DACG de comercialización','CAPÍTULO II · De la actividad de Comercialización',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('521c2f4f-a62a-508f-ae6c-8f6abe01e91e','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 7','<p> CAPÍTULO III<br/> </p>
<p> De las solicitudes de permisos de Comercialización<br/> </p>
<p> Artículo 7. Independencia de las solicitudes. De conformidad con el artículo 106 del Reglamento de la Ley del Sector Hidrocarburos, las solicitudes de otorgamiento de permiso de Comercialización deben presentarse de manera individualizada y el permiso debe otorgarse de manera independiente para Gas Natural, Petrolíferos o Petroquímicos y para el caso específico del Gas Licuado de Petróleo debe ser otorgado de manera independiente a los demás Petrolíferos.</p>
<p> En el caso de que se otorguen los permisos que encuadren en el artículo 2, fracción IV de estas Disposiciones, se debe establecer expresamente, en los títulos correspondientes, que las personas Permisionarias únicamente pueden comercializar Gas Natural, Petrolíferos, Gas Licuado de Petróleo o Petroquímicos obtenidos de sus propios procesos productivos, por lo que no pueden adquirir productos de terceros para su posterior comercialización al amparo de dichos permisos. Lo anterior con excepción de aquellos casos en donde se haya establecido así en el permiso de Comercialización correspondiente.</p>',9,'ordinario','DACG de comercialización','CAPÍTULO III · De las solicitudes de permisos de Comercialización',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('a7eee922-7f82-5070-bedc-2bc58b4197a2','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 8','<p> Artículo 8. Registro en la Oficialía de Partes Electrónica. Las Personas solicitantes y las personas Permisionarias de Comercialización deben realizar y mantener actualizado su registro en la Oficialía de Partes Electrónica, de conformidad con las Reglas Generales.</p>',10,'ordinario','DACG de comercialización','CAPÍTULO III · De las solicitudes de permisos de Comercialización',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('d61f763e-bdad-58b7-89f9-42b6be70585e','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 9','<p> Artículo 9. Pago de derechos o aprovechamientos. Previo a la presentación de la solicitud, la Persona solicitante debe realizar el pago de los derechos o aprovechamientos que correspondan al otorgamiento del permiso.</p>
<p> El pago se efectúa en una sola exhibición y por el monto vigente a la fecha de presentación de la solicitud, conforme a la Normatividad aplicable y, en su caso, el autorizado por la Secretaría de Hacienda y Crédito Público, publicado en el Diario Oficial de la Federación.</p>
<p> Para acreditar el pago, la Persona solicitante debe adjuntar a su solicitud el comprobante de derechos o aprovechamientos, el cual debe contener la siguiente información:</p>
<p> I.          Cadena de la Dependencia;</p>
<p> II.         Llave de pago;</p>
<p> III.        Monto pagado, y</p>
<p> IV.        Fecha de pago.</p>',11,'ordinario','DACG de comercialización','CAPÍTULO III · De las solicitudes de permisos de Comercialización',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('cecc9898-bc5f-522e-b885-642db67d7c0f','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 10','<p> Artículo 10. Requisitos de identificación de la Persona solicitante. Las Personas solicitantes que presenten la solicitud de otorgamiento de permiso de Comercialización, de conformidad con lo previsto en los artículos 80, de la Ley del Sector Hidrocarburos y 96 del Reglamento de la Ley del Sector Hidrocarburos y la Normatividad aplicable, deben proporcionar, mediante el formato establecido en el Anexo I de las presentes Disposiciones, la información y documentación siguiente, según el tipo de persona de que se trate:</p>
<p> A.    Datos de la Persona solicitante:</p>
<p> I.        Tipo de persona:</p>
<p> a)    Física;</p>
<p> b)    Moral;</p>
<p> c)     Entidad paraestatal, o</p>
<p> d)    Empresa pública del Estado;</p>
<p> II.       Tipo de empresa:</p>
<p> a)    Nacional, o</p>
<p> b)    Extranjera;</p>
<p>          En caso de ser empresa extranjera, la Persona solicitante debe estar constituida conforme a las leyes mexicanas, acorde con el artículo 331, fracción VI del Reglamento de la Ley del Sector Hidrocarburos.</p>
<p> III.      Mercado solicitado:</p>
<p> a)    Gas Natural;</p>
<p> b)    Petrolíferos;</p>
<p> c)     Gas Licuado de Petróleo, o</p>
<p> d)    Petroquímicos;</p>
<p> IV.      Título de Asignación, Contrato para la Exploración y Extracción o título de permiso, con el que cuenta, conforme al artículo 2, fracción IV de las Disposiciones:</p>
<p> a)    Título de Asignación;</p>
<p> b)    Contrato para la Exploración y Extracción;</p>
<p> c)     Refinación de Petróleo;</p>
<p> d)    Procesamiento de Gas Natural, o</p>
<p> e)    Formulación;</p>
<p> B.    Personas físicas. Deben presentar la siguiente información y documentación:</p>
<p> I.        Nombre completo;</p>
<p> II.       Identificación oficial vigente;</p>
<p> III.      RFC;</p>
<p> IV.      Opinión de cumplimiento de obligaciones fiscales en sentido positivo de la Persona solicitante, emitida por el Servicio de Administración Tributaria, con una antigüedad no mayor a tres meses a la fecha de presentación de la solicitud, y</p>
<p> V.       Descripción de la actividad que pretende realizar, que acredite que esta se encuentra directamente vinculada con su actividad económica conforme a su régimen fiscal.</p>
<p> C.    Personas morales, entidades paraestatales o empresas públicas del Estado. Deben presentar la siguiente información y documentación:</p>
<p> I.        Denominación o razón social;</p>
<p> II.       Acta constitutiva y, en su caso, las modificaciones inscritas en el Registro Público de Comercio, con las que se acredite su existencia legal y que el objeto social de la Persona solicitante se encuentre directamente vinculado con su actividad económica conforme a su régimen fiscal y con la actividad para la cual solicita el permiso; en el caso de entidades paraestatales y empresas públicas del Estado, el documento oficial de su creación o aquel que corresponda conforme a su naturaleza;</p>
<p> III.      RFC;</p>
<p> IV.      Opinión de cumplimiento de obligaciones fiscales en sentido positivo de la persona moral solicitante, emitida por el Servicio de Administración Tributaria, con una antigüedad no mayor a tres meses, y</p>
<p> V.       Estructura accionaria y corporativa de la sociedad y del capital social de la Persona solicitante, precisando la aportación o porcentaje de participación de cada socio o accionista, las acciones, e identificando a las personas o grupo de personas que tienen el control de la sociedad de manera directa o indirecta, señalando su nombre completo, denominación o razón social, y su RFC. Se entiende por grupo de personas aquellas que tengan acuerdos, de cualquier naturaleza, para tomar decisiones en un mismo sentido.</p>
<p> D.    Representante legal o persona apoderada. Además de los requisitos que correspondan a la Persona solicitante, se debe presentar lo siguiente:</p>
<p> I.        Nombre completo del representante legal o persona apoderada;</p>
<p> II.       Identificación oficial vigente;</p>
<p> III.      Instrumento notarial en el que conste el poder otorgado por la persona moral o física solicitante al representante legal o persona apoderada, así como sus facultades;</p>
<p> IV.      RFC, y</p>
<p> V.       Opinión del cumplimiento de obligaciones fiscales en sentido positivo, emitida por el Servicio de Administración Tributaria, con una antigüedad no mayor a tres meses a la fecha de presentación de la solicitud.</p>
<p> La información referida en el presente artículo se tiene por presentada siempre y cuando la Persona solicitante haya acreditado el registro en la Oficialía de Partes Electrónica y debe mantener actualizada la información correspondiente, de conformidad con las Reglas Generales.</p>',12,'ordinario','DACG de comercialización','CAPÍTULO III · De las solicitudes de permisos de Comercialización',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('955389ea-3de8-59cf-a433-3c17f7dc848c','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 11','<p> Artículo 11. Requisitos generales de la solicitud. Las Personas solicitantes además de la información contenida en el artículo anterior de las presentes Disposiciones, deben proporcionar en su solicitud de otorgamiento de permiso mediante el formato establecido en el Anexo I de las presentes Disposiciones, los siguientes requisitos generales:</p>
<p> I.          Domicilio fiscal de la Persona solicitante, que comprende:</p>
<p> a)    Código Postal;</p>
<p> b)    Entidad Federativa;</p>
<p> c)     Municipio o Alcaldía;</p>
<p> d)    Colonia;</p>
<p> e)    Calle;</p>
<p> f)     Número exterior, y</p>
<p> g)    Número interior;</p>
<p> II.         Domicilio y datos para oír y recibir notificaciones, consistentes en:</p>
<p> a)    Código Postal;</p>
<p> b)    Entidad Federativa;</p>
<p> c)     Municipio o Alcaldía;</p>
<p> d)    Colonia;</p>
<p> e)    Calle;</p>
<p> f)     Número exterior;</p>
<p> g)    Número interior, en su caso;</p>
<p> h)    Comprobante del domicilio para oír y recibir notificaciones, el cual debe coincidir íntegramente con el señalado en la solicitud y estar a nombre de la Persona solicitante, de su representante legal o personas autorizadas para oír y recibir notificaciones, conforme al artículo 108, fracción IX del Reglamento de la Ley del Sector Hidrocarburos, con una antigüedad no mayor a tres meses a la fecha de presentación de la solicitud;</p>
<p> i)     Nombre de la persona o personas autorizadas para oír y recibir notificaciones, y</p>
<p> j)     Correo electrónico;</p>
<p> III.        Grupo de Interés Económico. La Persona solicitante debe manifestar si pertenece o no a un Grupo de Interés Económico y, en caso afirmativo, proporcionar:</p>
<p> a)    La denominación o nombre del Grupo de Interés Económico, y</p>
<p> b)    Detalle las empresas integrantes del Grupo de Interés Económico:</p>
<p> i.      Denominación o la razón social de las personas integrantes;</p>
<p> ii.     Tipo de personas;</p>
<p> iii.    Nombre de sus socios o accionistas;</p>
<p> iv.    RFC;</p>
<p> v.     Aportación o porcentaje de participación, e</p>
<p> vi.    Indicar si ejercen control directo o indirecto.</p>',13,'ordinario','DACG de comercialización','CAPÍTULO III · De las solicitudes de permisos de Comercialización',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('b1d677b4-f8f5-5c3b-9d80-b7792a376634','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 12','<p> Artículo 12. Requisitos específicos sobre la actividad de Comercialización. Además de los requisitos señalados en los artículos 10 y 11 de las presentes Disposiciones, de conformidad con el artículo 108 del Reglamento de la Ley del Sector Hidrocarburos, las Personas solicitantes deben presentar mediante el formato establecido en el Anexo I de las presentes Disposiciones los siguientes requisitos:</p>
<p> I.          Listado de productos que se pretendan comercializar, debe incluir:</p>
<p> a)    Nombre del producto, y</p>
<p> b)    Volumen a comercializar expresado en la unidad correspondiente a cada producto, ya sea en litros, kilogramos, metros cúbicos, MMBTU o Giga Joules, según corresponda;</p>
<p> II.         Cartas de intención de compra o documento equivalente, suscritas por cada uno de sus potenciales clientes, en hoja membretada, con una antigüedad no mayor a seis meses a la fecha de presentación de la solicitud, que contengan:</p>
<p> a)    Lugar y fecha de expedición;</p>
<p> b)    Nombre del cliente potencial;</p>
<p> c)     Número de permiso otorgado por la Comisión del cliente potencial, en su caso;</p>
<p> d)    Actividad del cliente potencial;</p>
<p> e)    Producto por adquirir;</p>
<p> f)     Procedencia del producto a adquirir: importación, producción propia, adquisición de otra persona Permisionaria de Comercialización y, para este último caso, señalar si es Permisionaria de alguna otra actividad:</p>
<p> i.      Refinación de Petróleo;</p>
<p> ii.     Procesamiento de Gas Natural;</p>
<p> iii.    Formulación, o</p>
<p> iv.    Importación;</p>
<p> g)    Volumen ofertado de venta por cada producto a comercializar, y</p>
<p> h)    Nombre y firma de la persona representante legal de cada uno de los clientes potenciales;</p>
<p> III.        Cartas de intención de compra o documento equivalente, suscritas por cada uno de sus potenciales proveedores, en hoja membretada, con una antigüedad no mayor a seis meses a la fecha de presentación de la solicitud, que contengan:</p>
<p> a)    Lugar y fecha de expedición;</p>
<p> b)    Nombre del proveedor potencial;</p>
<p> c)     Número de permiso del proveedor potencial, en su caso;</p>
<p> d)    Actividad del proveedor potencial;</p>
<p> e)    Producto que provee;</p>
<p> f)     Volumen ofertado de compra por cada producto a comercializar, y</p>
<p> g)    Nombre y firma de la persona representante legal de cada uno de los proveedores potenciales.</p>
<p>             La información requerida en esta fracción no es aplicable a las Personas solicitantes cuyos productos a comercializar sean resultado de sus procesos productivos conforme al artículo 2, fracción IV, de las presentes Disposiciones;</p>
<p> IV.        Descripción de la zona geográfica de influencia de las actividades de Comercialización. En este apartado se debe proporcionar la información siguiente:</p>
<p> a)    Ubicación georreferenciada de los puntos de origen de los productos a comercializar, incluidos los puntos de recepción y carga, indicando las instalaciones involucradas, su tipo y, en su caso, el número de permiso respectivo;</p>
<p> b)    En su caso, ubicación georreferenciada de las instalaciones en las que se prestan los servicios de valor agregado que se pretendan incluir y gestionar con la actividad de Comercialización, indicando, en su caso, el número de permiso respectivo, y</p>
<p> c)     Ubicación georreferenciada de los puntos de destino previstos, incluidos los puntos de descarga y entrega, resultado de su actividad de Comercialización, indicando el tipo de instalación, sea de Transporte, Almacenamiento o Distribución, puertos o terminales marítimas para la Exportación o, en su caso, Instalaciones de Aprovechamiento, así como, en su caso, el número de permiso respectivo.</p>
<p>        La ubicación georreferenciada debe expresarse en coordenadas geográficas de latitud y longitud, en grados decimales;</p>
<p> V.         Mapa georreferenciado, en formato KMZ, correspondiente que incluya los elementos requeridos en la fracción anterior y aquellos que la Persona solicitante estime convenientes para visualizar la zona geográfica de influencia de las actividades relacionadas con la Comercialización;</p>
<p> VI.        Análisis de la demanda proyectada que se pretende atender por cada producto a comercializar, para lo cual se debe de señalar:</p>
<p> a)    Número estimado y tipo de persona Usuaria que demanda el producto, indicando si esta es Permisionaria de alguna de las actividades reguladas: Exportación, Comercialización, Distribución, Expendio al Público o Usuarios Finales;</p>
<p> b)    Número estimado y tipo de persona Usuaria Final que demanda el producto, indicando si esta es Permisionaria de Transporte o Almacenamiento para Usos Propios o de Despacho para Autoconsumo;</p>
<p> c)     Proyección anual de volúmenes de venta por la vigencia del permiso, expresada en la unidad correspondiente a cada producto, ya sea en litros, en kilogramos, metros cúbicos o MMBTU o Giga Joules, y</p>
<p> d)    Documento que explique la metodología para estimar la demanda y que permita replicar la estimación;</p>
<p> VII.       Carta de aceptación que establezca el volumen de reserva de capacidad en sus sistemas, por parte de la Permisionaria de Transporte, Almacenamiento o Distribución de la cual requiere dichos servicios, que contenga:</p>
<p> a)    Razón social de la Permisionaria;</p>
<p> b)    Capacidad total del Sistema de Transporte, Almacenamiento o Distribución;</p>
<p> c)     Capacidad operada del Sistema de Transporte, Almacenamiento o Distribución;</p>
<p> d)    Capacidad reservada del sistema de Transporte, Almacenamiento o Distribución;</p>
<p> e)    Periodo de reserva de capacidad, y</p>
<p> f)     Firma del representante legal de la Permisionaria de Transporte, Almacenamiento o Distribución.</p>
<p>             Lo anterior, sin perjuicio de las excepciones previstas en el Reglamento de la Ley del Sector Hidrocarburos;</p>
<p> VIII.      Origen del producto que se pretende comercializar:</p>
<p> a)    Razón social que suministra el producto, y</p>
<p> b)    Número de permiso del proveedor del producto.</p>
<p>             Esta información no es requerida para las Personas solicitantes referidas en el artículo 2,  fracción IV de las Disposiciones;</p>
<p> IX.        Documento con el que la Persona solicitante se compromete a garantizar la continuidad y seguridad de suministro, en el que indique:</p>
<p> a)    Fases operativas para el desarrollo de las actividades de Comercialización;</p>
<p> b)    Condiciones que propician un trato igualitario a los clientes;</p>
<p> c)     Mecanismos para la celebración de contratos con clientes y proveedores;</p>
<p> d)    Descripción detallada de la logística operativa que se debe implementar para el manejo de los productos objeto del permiso e incluir la interrelación con otras actividades reguladas aplicables en su caso, puntos de recepción, descarga, Transporte, Almacenamiento o Distribución hasta su destino final; identificar los medios utilizados, las instalaciones involucradas y los prestadores de servicios participantes en cada etapa del proceso, así como los permisos respectivos, lo anterior con el objeto de permitir la Trazabilidad del recurso energético o producto desde su origen;</p>
<p> e)    Análisis de mercado, donde se demuestre que existen las condiciones para garantizar la continuidad de la actividad regulada y que incluya:</p>
<p> i.      Estudio de la oferta;</p>
<p> ii.     Estudio de la demanda;</p>
<p> iii.    Estudio de la competencia;</p>
<p> iv.    Tendencias del mercado, y</p>
<p> v.     Estudio de precios del mercado;</p>
<p> X.         Modelo de contrato de Comercialización que se pretende suscribir con sus clientes, conforme a lo establecido en el artículo 49 de las presentes Disposiciones;</p>
<p> XI.        Descripción del proyecto de Comercialización. En caso de que se encuentre asociado a proyectos de Exploración y Extracción, Procesamiento de Gas Natural, Formulación y Refinación de Petróleo debe señalar por lo menos:</p>
<p> a)    Ubicación del proyecto;</p>
<p> b)    Monto de inversión;</p>
<p> c)     Personas asociadas al proyecto;</p>
<p> d)    Vigencia de la Asignación, Contrato para la Exploración y Extracción o permiso correspondiente, y</p>
<p> e)    Número de los permisos asociados a dichas actividades y vigencia de los contratos que, en su caso, se tengan con el gobierno mexicano.</p>
<p>             Debe señalarse el monto de inversión, en pesos mexicanos, en términos del artículo 80, fracción VIII, de la Ley del Sector Hidrocarburos.</p>',14,'ordinario','DACG de comercialización','CAPÍTULO III · De las solicitudes de permisos de Comercialización',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('04c0b7a7-3a39-5d8b-a7ff-421b29b9748c','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 13','<p> Artículo 13. Requisitos adicionales para la Comercialización de Petrolíferos distintos al Gas Licuado de Petróleo. Además de los requisitos señalados en los artículos 10, 11 y 12 de las presentes Disposiciones, en el caso de Comercialización de Petrolíferos, distintos al Gas Licuado de Petróleo, las Personas solicitantes deben presentar lo siguiente en la solicitud:</p>
<p> I.          Productos y, en su caso, subproductos que pretende comercializar;</p>
<p> II.         Marca comercial con la cual pretende llevar a cabo la actividad de Comercialización, y</p>
<p> III.        Carta de intención celebrada con el proveedor del servicio de Almacenamiento a fin de dar cumplimiento a la Política de Almacenamiento Mínimo de Petrolíferos, en caso de ubicarse en alguno de los supuestos siguientes:</p>
<p> a)    Vender diésel y, en su caso gasolinas, o</p>
<p> b)    Vender a Usuarios Finales o estaciones de servicio de Expendio al Público.</p>',15,'ordinario','DACG de comercialización','CAPÍTULO III · De las solicitudes de permisos de Comercialización',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('5276cd3e-e349-5e07-ab86-c4ba023d6faf','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 14','<p> Artículo 14. Requisitos adicionales para la Comercialización de Gas Natural. Las Personas solicitantes de un permiso de Comercialización de Gas Natural, además de los requisitos señalados en los artículos 10, 11 y 12 de las Disposiciones, deben presentar el documento con la descripción del análisis de la calidad del Gas Natural, en el que se indiquen los medios por los que se conoce la información relativa a la calidad del Gas Natural comprado y vendido.</p>
<p> Asimismo, dicho documento debe incluir los protocolos o convenios de medición, relativos al análisis de la calidad del Gas Natural que pretende establecer con las Permisionarias de Transporte, Almacenamiento o Distribución.</p>',16,'ordinario','DACG de comercialización','CAPÍTULO III · De las solicitudes de permisos de Comercialización',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('9cfc6a65-3c3f-53c8-af39-b708c625da0c','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 15','<p> Artículo 15. Manifestaciones y declaraciones. De conformidad con los artículos 80 de la Ley del Sector Hidrocarburos y 96 y 331 de su Reglamento, las Personas solicitantes deben aceptar dentro de su solicitud las siguientes manifestaciones y declaraciones bajo protesta de decir verdad:</p>
<p> I.          Que no se encuentra en el directorio de licitantes, proveedores o contratistas sancionados, conforme a la normativa vigente;</p>
<p> II.         Que no tiene incumplimientos vigentes en otros permisos;</p>
<p> III.        Que no se encuentra incluida en la relación de contribuyentes con operaciones presuntamente inexistentes a la que se refiere el artículo 69-B del Código Fiscal de la Federación;</p>
<p> IV.        Que no participa ni ejerce actividades ilícitas y que no realiza ni ha sido sancionada por actos de corrupción;</p>
<p> V.         Que tiene conocimiento del marco regulatorio aplicable a la actividad a desarrollar, y se compromete a cumplirlo;</p>
<p> VI.        Que otorga el consentimiento para recibir notificaciones, requerimientos, y las comunicaciones derivadas del trámite por medios electrónicos;</p>
<p> VII.       Que se compromete a presentar y mantener vigentes las garantías y los seguros correspondientes que pudieran derivarse de las actividades objeto del permiso, en términos del artículo 109, fracción X, del Reglamento de la Ley del Sector Hidrocarburos;</p>
<p> VIII.      Que declara que toda la información y documentación que se presenta en el trámite es verdadera, completa y exacta;</p>
<p> IX.        Que no ha realizado o realiza las actividades previstas en el artículo 3 de la Ley sin el permiso correspondiente;</p>
<p> X.         Que se encuentra constituido conforme a las leyes mexicanas;</p>
<p> XI.        Que no tiene un empleo, cargo o comisión, en cualquier ente público o privado, del que se desprenda un conflicto de interés;</p>
<p> XII.       Que no existe sentencia condenatoria firme por la comisión de delitos en materia de Hidrocarburos, en contra de un Particular, su representante legal o alguno de los accionistas o socios para el caso de Personas Morales, y</p>
<p> XIII.      Que acepta que la información proporcionada en el trámite sea protegida conforme a las disposiciones aplicables en materia de transparencia, acceso a la información pública y protección de datos personales.</p>',17,'ordinario','DACG de comercialización','CAPÍTULO III · De las solicitudes de permisos de Comercialización',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('ca6767ca-9525-5a62-b4f6-71d03d3f22a2','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 16','<p> CAPÍTULO IV<br/> </p>
<p> De la evaluación y resolución de las solicitudes<br/> </p>
<p> Artículo 16. Evaluación y resolución de la solicitud. La Comisión debe analizar, evaluar y resolver las solicitudes de otorgamiento de permiso previstas en las presentes Disposiciones, de conformidad con los términos y plazos establecidos en los artículos 142 y 143 del Reglamento de la Ley del Sector Hidrocarburos.</p>
<p> Concluida la evaluación de la solicitud, la Comisión debe resolver el otorgamiento o negación del permiso correspondiente, considerando los criterios de evaluación previstos en el artículo 81 de la Ley del Sector Hidrocarburos, la planeación vinculante y lo dispuesto en el artículo 152 del Reglamento de la Ley del Sector Hidrocarburos.</p>
<p> El otorgamiento del permiso de Comercialización se debe condicionar a través de la resolución correspondiente a que, dentro de los quince días hábiles siguientes a su notificación se presenten los contratos formalizados que deriven de las cartas de intención o equivalentes presentadas en términos de las fracciones II, III y VI del artículo 108 del Reglamento de la Ley del Sector Hidrocarburos.</p>
<p> Cuando la Comisión no emita una resolución dentro del plazo legalmente previsto, la solicitud de otorgamiento de permiso se debe entender resuelta en sentido negativo, de conformidad con lo establecido en el artículo 146, primer párrafo, del Reglamento de la Ley del Sector Hidrocarburos.</p>
<p> A petición de la Persona solicitante, la Comisión debe expedir la constancia de la resolución en sentido negativo dentro de los dos días hábiles siguientes a la presentación de dicha petición, de conformidad con el artículo 17 de la Ley Federal de Procedimiento Administrativo.</p>
<p> La Comisión debe resolver en sentido negativo cuando exista presunción fundada de que el otorgamiento del permiso pueda propiciar la realización de actividades ilícitas en materia de Hidrocarburos, en términos del artículo 152, segundo párrafo, del Reglamento de la Ley del Sector Hidrocarburos.</p>
<p> En caso de que el permiso sea negado, queda a salvo el derecho de la Persona solicitante para presentar una nueva solicitud de otorgamiento de permiso, para lo cual debe acreditar el nuevo pago de derechos o aprovechamientos, que resulte procedente y cumplir nuevamente con los requisitos señalados en las presentes Disposiciones.</p>',18,'ordinario','DACG de comercialización','CAPÍTULO IV · De la evaluación y resolución de las solicitudes',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('3889bc9e-65bf-5552-8554-c63dcad6466f','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 17','<p> Artículo 17. Requerimiento de información adicional. Concluido el plazo para atender la prevención, la Comisión puede requerir a la Persona solicitante, por única ocasión, la presentación de documentación o aclaraciones relacionadas con la información presentada, para lo cual debe otorgarse un plazo de hasta diez días hábiles para su atención, durante el cual se suspende el plazo para resolver, en términos del artículo 143, fracción IV, del Reglamento de la Ley del Sector Hidrocarburos.</p>
<p> Asimismo, en cualquier momento del procedimiento de evaluación, la Comisión puede realizar investigaciones, recabar información de otras fuentes, consultar a cualquier autoridad de los tres órdenes de gobierno, celebrar comparecencias y, en general, llevar a cabo cualquier acción que considere necesaria para mejor proveer en la resolución de la solicitud de otorgamiento de permiso, de conformidad con el último párrafo del artículo 143 del citado Reglamento.</p>',19,'ordinario','DACG de comercialización','CAPÍTULO IV · De la evaluación y resolución de las solicitudes',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('1c4cc1f7-b804-5f27-97ef-141dc6a46628','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 18','<p> Artículo 18. Limitaciones para el otorgamiento del permiso. Además de los criterios establecidos en el artículo 331 del Reglamento de la Ley del Sector Hidrocarburos, la Comisión no debe otorgar el permiso de Comercialización cuando determine que se actualice alguno de los siguientes supuestos:</p>
<p> I.          Se identifique que los potenciales proveedores o clientes de la Persona solicitante sean, a su vez, personas Permisionarias de Comercialización, que se encuentren en alguno de los supuestos de sanción referidos en el artículo 121, fracción II, incisos a), f) o i) de la Ley del Sector Hidrocarburos;</p>
<p> II.         Cuando del análisis de la información presentada, así como de la demás con la que cuente la Comisión en el ejercicio de sus atribuciones, exista presunción fundada de que el otorgamiento del permiso pueda propiciar la realización de actividades ilícitas en materia de Hidrocarburos, y</p>
<p> III.        Se tenga registro que la Persona solicitante o el Grupo de Interés Económico al que pertenece se le haya revocado alguno de los permisos de las actividades reguladas, derivado de las siguientes causales:</p>
<p> a)    Haber realizado prácticas indebidamente discriminatorias en perjuicio de las personas Usuarias;</p>
<p> b)    Haber realizado actividades de Transporte, Almacenamiento, Distribución o Expendio al Público de Hidrocarburos, Petrolíferos o Petroquímicos, que hayan sido adquiridos de forma ilícita o por la comisión del delito de contrabando de Hidrocarburos, Petrolíferos y Petroquímicos, y que haya sido así determinado por resolución firme de autoridad competente;</p>
<p> c)     Haber faltado al cumplimiento de la entrega de la información que permitiera a la Secretaría o a la Comisión conocer los controles volumétricos, medición, calidad de los Hidrocarburos, Petrolíferos y Petroquímicos, objeto de los permisos respectivos, así como de las operaciones comerciales con clientes y proveedores, y demás información que la Secretaría o la Comisión requieren para fines de supervisión y estadísticos del sector energético;</p>
<p> d)    Ubicarse en alguno de los supuestos establecidos en el artículo 69, penúltimo párrafo, del Código Fiscal de la Federación y cuyo nombre, denominación o razón social y clave en el RFC se encuentren contenidos en la publicación de la página de Internet del Servicio de Administración Tributaria a que se refiere el último párrafo del citado artículo, o</p>
<p> e)    Encontrarse publicada en definitiva en el listado previsto en el cuarto párrafo del artículo 69-B del Código Fiscal de la Federación, o bien, sea uno de sus socios o accionistas el que se encuentre publicado en dicho listado.</p>
<p> La resolución que niegue el otorgamiento del permiso de Comercialización debe estar debidamente fundada y motivada e identificar el supuesto que se actualiza, los hechos y elementos que lo acreditan y su relación con la solicitud evaluada.</p>
<p> Los supuestos previstos en este artículo también resultan aplicables, según corresponda, a las solicitudes de modificación y de autorización de cesión de permisos.</p>',20,'ordinario','DACG de comercialización','CAPÍTULO IV · De la evaluación y resolución de las solicitudes',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('14dffdcc-9ffb-5658-b603-fd2ddf671767','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 19','<p> CAPÍTULO V<br/> </p>
<p> De las Vigencias de los Permisos<br/> </p>
<p> Artículo 19. Vigencias. La Comisión puede otorgar los permisos de Comercialización con una vigencia de hasta dos años, previa evaluación de las características particulares de cada proyecto, de conformidad con lo previsto en el artículo 81, primer párrafo de la Ley del Sector Hidrocarburos, la Normatividad aplicable y, al menos, los criterios técnicos, económicos y regulatorios establecidos en el artículo 93 del Reglamento de la Ley del Sector Hidrocarburos.</p>',21,'ordinario','DACG de comercialización','CAPÍTULO V · De las Vigencias de los Permisos',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('73e72885-0c65-5bf4-b956-c19b8721a23a','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 20','<p> Artículo 20. Derecho a solicitar un nuevo permiso. Para continuar sus actividades después del vencimiento de la vigencia del permiso, las personas Permisionarias de Comercialización deben obtener un nuevo permiso conforme a lo establecido en los artículos 93, último párrafo y 143 del Reglamento de la Ley del Sector Hidrocarburos. La presentación de la solicitud no debe entenderse como una prórroga automática respecto de la vigencia del permiso existente.</p>',22,'ordinario','DACG de comercialización','CAPÍTULO V · De las Vigencias de los Permisos',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('f7b6fb83-9973-5521-b911-b2f9a555b5c1','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 21','<p> CAPÍTULO VI<br/> </p>
<p> De las Actualizaciones y Modificaciones de los Permisos<br/> </p>
<p> Artículo 21. Causales de modificación. Los permisos de Comercialización de Gas Natural, Petrolíferos, Gas Licuado de Petróleo y Petroquímicos pueden ser modificados a petición de parte o de oficio, de conformidad con los artículos 86, primero, segundo y tercer párrafos y 116, fracción I, incisos a), b) y c) de la Ley del Sector Hidrocarburos y 147, 148 y 150 del Reglamento de la Ley del Sector Hidrocarburos. Las causales de modificación a petición de parte son las siguientes:</p>
<p> I.          Cesión del permiso;</p>
<p> II.         Fusión de sociedades;</p>
<p> III.        Sucesión del permiso, y</p>
<p> IV.        Escisión de sociedades.</p>
<p> La modificación al permiso de Comercialización no implica una ampliación de su vigencia, por lo que mantiene la vigencia originalmente otorgada.</p>',23,'ordinario','DACG de comercialización','CAPÍTULO VI · De las Actualizaciones y Modificaciones de los Permisos',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('5e1be2f0-94a5-5ca9-bcda-942627ee6429','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 22','<p> Artículo 22. Requisitos generales de las solicitudes de modificación. Toda solicitud de modificación del permiso de Comercialización a petición de parte debe presentarse a través de la Oficialía de Partes Electrónica, conforme al formato que corresponda de conformidad con las presentes Disposiciones y acompañarse de lo siguiente:</p>
<p> I.          Número del permiso objeto de la solicitud;</p>
<p> II.         Comprobante del pago de los derechos o aprovechamientos correspondientes, en términos del artículo 147, primer párrafo, del Reglamento de la Ley del Sector Hidrocarburos, el cual debe contener la información señalada en el artículo 9 de las Disposiciones;</p>
<p> III.        Descripción de la modificación solicitada y su justificación;</p>
<p> IV.        Las manifestaciones bajo protesta de decir verdad señaladas en el artículo 15 de las Disposiciones en lo conducente, y</p>
<p> V.         Además de las manifestaciones anteriores, la manifestación bajo protesta de decir verdad que el permiso de Comercialización vigente se encuentra al corriente en el cumplimiento de todas sus obligaciones derivadas del permiso.</p>',24,'ordinario','DACG de comercialización','CAPÍTULO VI · De las Actualizaciones y Modificaciones de los Permisos',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('eb24ee9c-07ba-539e-b84c-01826a8e092b','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 23','<p> Artículo 23. Modificación del permiso por Cesión. La cesión solo procede previa autorización de la Comisión, cuando el permiso se encuentre vigente, la persona cedente haya cumplido con todas sus obligaciones y la persona cesionaria reúna los requisitos para ser persona Permisionaria de Comercialización y se comprometa a cumplir en sus términos las obligaciones previstas en el permiso, en términos del artículo 86 de la Ley del Sector Hidrocarburos.</p>
<p> Para tal efecto, además de los requisitos previstos en el artículo anterior, se deben presentar los siguientes requisitos conforme al formato establecido en el Anexo II, sección 2 de las presentes Disposiciones:</p>
<p> I.          Contrato de cesión de derechos;</p>
<p> II.         Respecto de la persona cesionaria, se debe ingresar la información y documentación conforme a lo dispuesto en los artículos 10 y 11 de estas Disposiciones, y</p>
<p> III.        En su caso, indicar el número de resolución de la autorización de participación cruzada en términos de los artículos 118 de la Ley del Sector Hidrocarburos y 151 del Reglamento de la Ley del Sector Hidrocarburos.</p>',25,'ordinario','DACG de comercialización','CAPÍTULO VI · De las Actualizaciones y Modificaciones de los Permisos',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('cd6ab516-e8c7-505a-9f2a-57ac92ae2bf7','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 24','<p> Artículo 24. Modificación del permiso por Fusión de sociedades. En caso de que la persona Permisionaria de Comercialización requiera modificar el permiso de Comercialización por fusión, además de lo señalado en el artículo 22 de estas Disposiciones se debe presentar conforme al formato establecido en el Anexo III, Sección 2 de las Disposiciones, los siguientes requisitos:</p>
<p> I.          Instrumento notarial en el que conste la formalización de la fusión y, en su caso, la constancia de su inscripción en el Registro Público de Comercio, con los datos siguientes:</p>
<p> a)    Número del instrumento notarial;</p>
<p> b)    Fecha del instrumento notarial;</p>
<p> c)     Nombre de la persona fedataria, y</p>
<p> d)    Número de notaría o correduría, y</p>
<p> II.         Información y documentación de la sociedad fusionante, conforme a los artículos 10,  apartado C y 11 de estas Disposiciones.</p>',26,'ordinario','DACG de comercialización','CAPÍTULO VI · De las Actualizaciones y Modificaciones de los Permisos',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('ca67165c-6aa6-52e8-b4e4-a4f27bfcf474','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 25','<p> Artículo 25. Modificación del permiso por Sucesión del permiso. Tratándose del fallecimiento de la persona física titular del permiso, la Persona solicitante debe presentar los siguientes requisitos conforme al Anexo IV, Sección 2, además de lo señalado en el artículo 22 de estas Disposiciones:</p>
<p> I.          Acta de defunción de la persona Permisionaria de Comercialización;</p>
<p> II.         Documento con el que se acredite el carácter de heredera, legataria o albacea de la persona promovente, o la adjudicación de los derechos correspondientes, mediante resolución judicial o instrumento notarial, y</p>
<p> III.        Respecto de la persona que pretenda continuar con la actividad permisionada, la información y documentación señaladas en los artículos 10 y 11 de las Disposiciones.</p>
<p> En tanto se resuelve la solicitud, la persona albacea o quien acredite la representación de la sucesión puede continuar la operación de la actividad permisionada bajo las obligaciones del permiso, informándolo a la Comisión.</p>',27,'ordinario','DACG de comercialización','CAPÍTULO VI · De las Actualizaciones y Modificaciones de los Permisos',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('cbd43373-2c77-54e3-b6f9-e1bed6e6f1cb','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 26','<p> Artículo 26. Modificación del permiso por Escisión de sociedades. En caso de que la persona Permisionaria de Comercialización requiera modificar el permiso de Comercialización por escisión debe presentar la siguiente información adicional a la señalada en el artículo 22 y conforme al formato establecido en el Anexo V, Sección 2 de estas Disposiciones:</p>
<p> I.          Instrumento notarial en el que conste la formalización de la escisión y, en su caso, la constancia de su inscripción en el Registro Público de Comercio:</p>
<p> a)     Número del instrumento notarial;</p>
<p> b)     Fecha del instrumento notarial;</p>
<p> c)     Nombre de la persona fedataria;</p>
<p> d)     Número de notaría o correduría, y</p>
<p> e)     Constancia de inscripción en el Registro Público de Comercio, en su caso, y</p>
<p> II.         Respecto de la sociedad que queda como titular del permiso, la información y documentación señaladas en los artículos 10, apartados B y C y 11 de las Disposiciones, incluido el diagrama de la estructura accionaria y corporativa resultante.</p>',28,'ordinario','DACG de comercialización','CAPÍTULO VI · De las Actualizaciones y Modificaciones de los Permisos',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('be95870b-66fa-58ef-add5-828626f132f3','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 27','<p> Artículo 27. Acreditación del cumplimiento de obligaciones para la procedencia de las modificaciones. Para que proceda cualquier solicitud de modificación presentada a petición de parte por las causas previstas en el artículo 21 de las Disposiciones, la persona Permisionaria de Comercialización debe manifestar el cumplimiento de las obligaciones a que se refiere el Capítulo VII de las presentes Disposiciones, en lo que aplique a la fecha de presentación de su solicitud.</p>
<p> La Comisión debe verificar el cumplimiento de las obligaciones referidas como parte del análisis integral de la solicitud de modificación. En su caso, puede requerir información que permita acreditar la procedencia lícita de los productos que actualmente comercializa, así como la que acredite los volúmenes de inventarios de los productos a comercializar.</p>
<p> El incumplimiento de cualquiera de las obligaciones es causa de prevención para que se acredite su cumplimiento, sin perjuicio de las sanciones que procedan conforme a la Normatividad aplicable y de que, tratándose de la cesión, el incumplimiento de las obligaciones de la persona cedente sea causa para negar la modificación, en términos del artículo 86, primer párrafo, de la Ley del Sector Hidrocarburos.</p>',29,'ordinario','DACG de comercialización','CAPÍTULO VI · De las Actualizaciones y Modificaciones de los Permisos',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('8d06e42b-c053-5447-9d70-78d013d3ad87','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 28','<p> Artículo 28. Procedimiento y resolución de las modificaciones a petición de parte. Las solicitudes de modificación a petición de parte se deben tramitar conforme al procedimiento establecido en los artículos 143, en lo conducente, y 147 del Reglamento de la Ley del Sector Hidrocarburos y surten efectos a partir de que sean autorizadas y notificadas por la Comisión.</p>
<p> Para tales efectos, las referencias que el artículo 143 del Reglamento de la Ley del Sector Hidrocarburos hace a la Persona solicitante se entienden hechas a la persona Permisionaria de Comercialización titular del permiso vigente, y las referencias al otorgamiento del permiso se entienden hechas a la aprobación de la modificación de este.</p>
<p> Concluida la evaluación, la Comisión debe otorgar o negar la modificación. La falta de resolución dentro del plazo establecido se entiende resuelta en sentido negativo de conformidad con el artículo 146 del Reglamento de la Ley del Sector Hidrocarburos.</p>
<p> Otorgada la modificación, la Comisión debe expedir el instrumento mediante el cual conste la modificación al título de permiso, debiendo precisar los términos y alcances modificados, así como la fecha a partir de la cual surte efectos.</p>
<p> Negada la modificación solicitada por la persona Permisionaria de Comercialización, subsisten en sus términos los derechos y obligaciones consignados en el permiso vigente, quedando a salvo los derechos de aquélla para presentar una nueva solicitud, previo pago de los derechos o aprovechamientos que correspondan.</p>
<p> A partir de que surta efectos la notificación de la admisión de la solicitud, la Comisión, debe llevar a cabo el análisis y evaluación de esta dentro del plazo de noventa días naturales, contados a partir del día siguiente al de la recepción de la solicitud, en términos del artículo 86, segundo párrafo, de la Ley del Sector Hidrocarburos; transcurrido dicho plazo sin resolución expresa, esta se entiende en sentido negativo.</p>
<p> La cesión que se realice sin autorización de la Comisión es nula de pleno derecho, conforme al artículo 86, tercer párrafo, de la Ley del Sector Hidrocarburos.</p>',30,'ordinario','DACG de comercialización','CAPÍTULO VI · De las Actualizaciones y Modificaciones de los Permisos',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('9c1332d4-1424-5018-965a-a08f4aefd27d','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 29','<p> Artículo 29. Actualización del permiso por cambio de control. En caso de modificación a la estructura del capital social de la persona Permisionaria de Comercialización que implique un cambio de control corporativo o de gestión, se requiere una actualización del permiso, siempre que este se encuentre vigente y que la persona Permisionaria de Comercialización esté al corriente en el cumplimiento de todas sus obligaciones, en términos del artículo 86, cuarto párrafo, de la Ley del Sector Hidrocarburos.</p>
<p> La solicitud de actualización se debe presentar previo pago de los derechos o aprovechamientos correspondientes y se sustancia conforme al procedimiento previsto en el artículo 143 del Reglamento de la Ley del Sector Hidrocarburos, en lo conducente, de conformidad con el artículo 149 de ese mismo ordenamiento y demás normatividad aplicable que emita la Comisión.</p>',31,'ordinario','DACG de comercialización','CAPÍTULO VI · De las Actualizaciones y Modificaciones de los Permisos',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('7920565b-310a-5941-967d-191a2bfb7747','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 30','<p> Artículo 30. Requisitos para la actualización del permiso por cambio de control. La solicitud de actualización a que se refiere el artículo anterior debe acompañarse de la siguiente información y la referida en el artículo 22, conforme al Anexo VI de estas Disposiciones y demás normatividad aplicable:</p>
<p> I.          Diagrama de la estructura accionaria y corporativa, autorizada a través del otorgamiento del título de permiso o mediante algún documento oficial emitido por la Comisión, en los términos del artículo 10, Apartado C, fracción V, de estas Disposiciones;</p>
<p> II.         Diagrama de la estructura accionaria y corporativa que se pretende registrar;</p>
<p> III.        Instrumento público en el que conste el acto jurídico o corporativo que origine el cambio de control de que se trate, tales como las actas o instrumentos correspondientes a las asambleas de accionistas o socios, convenios entre socios o accionistas, contratos de transmisión de acciones o participaciones, o aquellos que resulten aplicables, y</p>
<p> IV.        Las inscripciones respectivas en el Registro Público de Comercio, en su caso.</p>',32,'ordinario','DACG de comercialización','CAPÍTULO VI · De las Actualizaciones y Modificaciones de los Permisos',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('3ef0d732-0ae8-5836-8265-463007ce6383','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 31','<p> Artículo 31. Modificación de oficio. La Comisión puede modificar de oficio los permisos que haya otorgado cuando los términos y condiciones originalmente aprobados ya no correspondan a las necesidades del servicio o afecten su seguridad, eficiencia, homogeneidad, regularidad, calidad y continuidad para garantizar la soberanía, autosuficiencia y justicia energética de la Nación, o para promover el desarrollo ordenado, continuo y seguro de las actividades del sector energético.</p>
<p> El procedimiento de modificación de oficio se sustancia conforme a las etapas, plazos y consecuencias previstas en el artículo 148 del Reglamento de la Ley del Sector Hidrocarburos. Las modificaciones de oficio no requieren el pago de derechos o aprovechamientos por parte de la persona Permisionaria de Comercialización.</p>',33,'ordinario','DACG de comercialización','CAPÍTULO VI · De las Actualizaciones y Modificaciones de los Permisos',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('f2581edb-fc36-5090-bea3-bd1b41e8418a','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 32','<p> Artículo 32. Subsistencia del permiso vigente durante la sustanciación. Durante la sustanciación del procedimiento para la modificación o actualización del permiso, subsisten en sus términos los derechos y obligaciones originalmente otorgados y manteniendo su vigencia.</p>
<p> La presentación de la solicitud no habilita a la persona Permisionaria de Comercialización a realizar las actividades, instalaciones, capacidades o condiciones cuya modificación se solicita, las cuales únicamente pueden ejecutarse a partir de que surta efectos la resolución que las autorice.</p>
<p> El otorgamiento de la modificación solicitada no implica la renovación de la vigencia originalmente otorgada en el permiso.</p>',34,'ordinario','DACG de comercialización','CAPÍTULO VI · De las Actualizaciones y Modificaciones de los Permisos',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('f13e477a-c7a2-52a7-bda3-fe03eaf44915','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 33','<p> CAPÍTULO VII<br/> </p>
<p> De las Obligaciones de las personas Permisionarias de Comercialización<br/> </p>
<p> Artículo 33. Obligaciones sobre la Comercialización. Las personas Permisionarias de Comercialización deben cumplir con las obligaciones previstas en la Ley del Sector Hidrocarburos, su Reglamento, estas Disposiciones, los títulos de permiso y demás Normatividad aplicable, de acuerdo con los productos y actividades que tienen autorizadas.</p>
<p> Derivado de lo señalado en el párrafo previo, las personas Permisionarias de Comercialización deben:</p>
<p> I.          Contar con el permiso vigente correspondiente y realizar sus actividades conforme a los términos, condiciones y alcances autorizados en el mismo;</p>
<p> II.         Abstenerse de ceder, traspasar, vender o gravar, total o parcialmente, los derechos u obligaciones derivados del permiso en contravención de la Ley del Sector Hidrocarburos;</p>
<p> III.        Tramitar las modificaciones, actualizaciones o autorizaciones que correspondan conforme a la Normatividad aplicable;</p>
<p> IV.        Notificar a la Comisión el inicio de sus operaciones, el cual no puede tener lugar antes de la aprobación del modelo de contrato de Comercialización correspondiente, en términos del artículo 54 de las Disposiciones;</p>
<p> V.         Formalizar sus relaciones comerciales mediante contratos congruentes con los alcances de su permiso considerando lo previsto en estas Disposiciones. Los contratos que deriven de las cartas de intención o documentos equivalentes previstos en el artículo 108 del Reglamento de la Ley del Sector Hidrocarburos deben amparar, por lo menos, la vigencia del permiso. Esto en relación con lo previsto en la fracción XXII de este artículo;</p>
<p> VI.        Corroborar, antes de realizar la transacción comercial, que su contraparte cuente con el permiso vigente cuando la actividad que realiza lo requiere, mediante consulta a la Secretaría o a la Comisión, o a través de las plataformas, herramientas tecnológicas y demás medios habilitados para ese efecto;</p>
<p> VII.       Abstenerse de contratar o prestar servicios, comprar o vender productos a particulares que realizan actividades sujetas a permiso sin contar con el mismo;</p>
<p> VIII.      Realizar sus actividades con productos de procedencia lícita y remitir a la Comisión los contratos celebrados con las personas proveedoras que acrediten el suministro y confirmen dicha procedencia, conforme al Capítulo XI de estas Disposiciones;</p>
<p> IX.        Prestar los servicios de forma eficiente, uniforme, homogénea, regular, segura y continua, y cumplir las disposiciones de seguridad de suministro que establezca la Secretaría, informando de manera inmediata a la Comisión cualquier circunstancia que impida el suministro de los productos autorizados, en los términos de la Normatividad aplicable o del título de permiso;</p>
<p> X.         Comprar, comercializar, vender y suministrar los productos sin alteración o adulteración, y entregar la cantidad y calidad que establezcan las disposiciones aplicables, siendo responsables de conservar la calidad y, en su caso, de realizar la medición del producto recibido y entregado objeto de su actividad;</p>
<p> XI.        Tratándose de Petrolíferos, tales como gasolinas y diésel, comercializar únicamente productos con una marca comercial previamente registrada ante la Comisión. Por cada contrato de servicio que formalicen, deben notificar a la Comisión, mediante el Formulario de Contratos, la marca del producto comercializado y declararla, a través del ContratoId, en cada transacción derivada de dicho contrato;</p>
<p> XII.       Mantener actualizado el padrón de personas proveedoras y clientes finales, y remitirlo semestralmente a la Comisión, conforme al Capítulo XI de estas Disposiciones, con los contratos vigentes, los volúmenes comprometidos y el destino final del producto;</p>
<p> XIII.      Observar los lineamientos aplicables a sus relaciones con personas que formen parte de su mismo grupo empresarial o consorcio;</p>
<p> XIV.      Abstenerse de otorgar subsidios cruzados en la prestación de los servicios permisionados y de realizar prácticas indebidamente discriminatorias, y respetar los precios o tarifas máximas que se establezcan en la Normatividad aplicable;</p>
<p> XV.       Obtener la autorización de la autoridad competente, incluida la correspondiente a sus modificaciones, con la opinión favorable previa de la autoridad competente en materia de competencia económica, cuando se actualicen los supuestos de participación cruzada previstos en los artículos 118 de la Ley del Sector Hidrocarburos y 109, fracción VIII, del Reglamento de la Ley del Sector Hidrocarburos. Lo anteriormente previsto no resulta aplicable al Grupo de Interés Económico del que forman parte las Empresas Públicas del Estado, en los términos del último párrafo del artículo 118 de la Ley del Sector Hidrocarburos;</p>
<p> XVI.      Otorgar y mantener vigentes las garantías y los seguros correspondientes, y cumplir de forma continua el pago de las contribuciones y aprovechamientos por los servicios de supervisión del permiso;</p>
<p> XVII.     Mantener actualizados ante la Comisión el domicilio y la dirección de correo electrónico para oír y recibir notificaciones;</p>
<p> XVIII.     Informar el cambio o actualización del domicilio acreditado dentro de los cinco días hábiles posteriores a que esto ocurra y presentar la documentación que lo acredite, conforme a lo previsto en la fracción XXX de este artículo;</p>
<p> XIX.      Contar con un servicio permanente de recepción y atención de quejas y dar aviso a la Comisión de las circunstancias que impliquen la modificación de los términos y condiciones de prestación del servicio;</p>
<p> XX.       Obtener autorización de la Comisión para suspender los servicios, salvo por caso fortuito o fuerza mayor, supuesto en el que deben informar de inmediato a dicha autoridad;</p>
<p> XXI.      Incluir en la factura el desglose de las actividades y su costo unitario, cuando el servicio de Comercialización incluya la gestión o contratación de Transporte, Almacenamiento o Distribución. Cuando existan componentes no desagregables o condiciones comerciales confidenciales, pueden incluir en la factura u orden de servicio una nota explicativa de esa circunstancia. La factura, orden de servicio o documento análogo que lo permita debe contener la información de contacto de las personas prestadoras de los servicios referidos, para que las personas Usuarias puedan contratarlos de manera directa;</p>
<p> XXII.     Informar y remitir a la Comisión los contratos mediante los cuales gestionen los servicios de Transporte, Almacenamiento o Distribución, necesarios para sus actividades, con señalamiento expreso de su vigencia y capacidad de volumen de los servicios anteriores, conforme al Capítulo XI de estas Disposiciones. Lo anterior, sin perjuicio de las excepciones previstas en el Reglamento de la Ley del Sector Hidrocarburos;</p>
<p> XXIII.     Cumplir con los límites de capacidad a contratar en Ductos de Distribución o Transporte, o en instalaciones de Almacenamiento, que establezcan la Secretaría o la Comisión, en el ámbito de sus atribuciones. La gestión o contratación de esos servicios se ajusta a los productos, volúmenes y condiciones amparados por los permisos correspondientes;</p>
<p> XXIV.    Cumplir, según corresponda a su actividad, las obligaciones previstas en el artículo 119, fracciones XXII, XXIII y XXIV, de la Ley del Sector Hidrocarburos y en las disposiciones fiscales aplicables, relativas a:</p>
<p> a)    Los equipos y programas informáticos para llevar controles volumétricos y los certificados que acrediten su correcta operación y funcionamiento;</p>
<p> b)    Los dictámenes de laboratorio que determinen el tipo de Hidrocarburo o Petrolífero, el poder calorífico del Gas Natural y el octanaje de las gasolinas, según corresponda, y</p>
<p> c)     Los registros diarios y reportes mensuales de controles volumétricos, con los datos de recepción, entrega y existencias, comprobantes fiscales o pedimentos asociados, dictámenes y certificados exigibles;</p>
<p> XXV.     Conservar los reportes de información de controles volumétricos durante los plazos establecidos en la Normatividad aplicable. El cumplimiento de estas obligaciones no sustituye la entrega semanal de información prevista en el artículo 76 de la Ley del Sector Hidrocarburos;</p>
<p> XXVI.    Cumplir las obligaciones de información que les resulten aplicables conforme al artículo 76 de la Ley del Sector Hidrocarburos, el Reglamento de la Ley del Sector Hidrocarburos y la regulación correspondiente;</p>
<p> XXVII.   Sujetarse a las limitaciones respecto de las operaciones que realicen entre personas Permisionarias de Comercialización que se establezcan en la Normatividad que emitan la Secretaría o la Comisión, en el ámbito de sus atribuciones, conforme al artículo 107 del Reglamento de la Ley del Sector Hidrocarburos;</p>
<p> XXVIII.   Incluir la gestión o contratación de servicios de Transporte, Almacenamiento o Distribución cuando las personas Permisionarias de Comercialización presten el servicio a otras personas Usuarias que también sean titulares de un permiso de Comercialización. Lo anterior, sin perjuicio de las excepciones previstas en el Reglamento de la Ley del Sector Hidrocarburos;</p>
<p> XXIX.    Preservar y mantener los respaldos documentales en formato físico o electrónico que sustenten las transacciones comerciales realizadas, incluyendo, de manera enunciativa mas no limitativa, los comprobantes fiscales digitales por Internet o CFDI, pedimentos de importación, contratos, órdenes de compra, entre otros;</p>
<p> XXX.     Presentar los reportes, el Formulario de Contratos y demás obligaciones en los plazos y términos establecidos en las presentes Disposiciones;</p>
<p> XXXI.    Proporcionar, registrar y validar información veraz, completa, consistente e íntegra en los reportes, el Formulario de Contratos y demás obligaciones establecidas en las presentes Disposiciones,</p>
<p> XXXII.   Atender en tiempo y forma los requerimientos de información o aclaraciones formulados por la Comisión en ejercicio de sus facultades de supervisión y verificación, y</p>
<p> XXXIII.   Mantener vigente y plenamente identificable su domicilio fiscal, así como el domicilio señalado para oír y recibir notificaciones conforme a lo previsto en la fracción XVIII de este artículo, los cuales deben corresponder a lugares ciertos, localizables y accesibles para la práctica de diligencias por parte de la Comisión.</p>
<p>             Para tal efecto, la Comisión puede, en cualquier momento, verificar la existencia, localización, ocupación y funcionamiento de los domicilios señalados, mediante visitas de verificación, requerimientos documentales, consultas a registros públicos o cualquier otro medio legalmente procedente.</p>
<p>             Para efectos de acreditar la existencia y materialidad del domicilio, los sujetos regulados deben conservar y proporcionar, cuando sean requeridos, elementos documentales y físicos que demuestren que en dicho lugar se desarrollan efectivamente actividades relacionadas con su objeto, actividad económica o cumplimiento de obligaciones regulatorias, incluyendo, de manera enunciativa mas no limitativa:</p>
<p> a)    Documentos que acrediten la legal posesión, uso o disfrute del inmueble;</p>
<p> b)    Comprobantes de servicios públicos o privados asociados al inmueble, y</p>
<p> c)     Evidencia de infraestructura, equipamiento, listado de personal y demás recursos materiales suficientes para el desarrollo de las actividades declaradas.</p>',35,'ordinario','DACG de comercialización','CAPÍTULO VII · De las Obligaciones de las personas Permisionarias de Comercialización',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('1060178e-f892-5666-a605-cea212ebb6cf','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 34','<p> Artículo 34. Obligaciones sobre la entrega de información. Las personas Permisionarias de Comercialización deben presentar la información de sus operaciones en los formatos, medios, términos y condiciones previstos en la Normatividad aplicable y cumplir, al menos, las obligaciones siguientes:</p>
<p> I.          Entregar semanalmente la información relacionada con controles volumétricos, medición, calidad del Gas Natural, Petrolíferos, Gas Licuado de Petróleo o Petroquímicos, objeto del permiso de Comercialización, así como de las operaciones comerciales, incluyendo las transacciones, inventarios y datos fiscales y regulatorios de las personas proveedoras, prestadoras de servicios y clientes, conforme al artículo 76 de la Ley del Sector Hidrocarburos;</p>
<p> II.         Informar semanalmente a la Comisión si prestan servicios o realizan intermediación de servicios de valor agregado en beneficio de las personas Usuarias o Usuarias Finales, por separado o en conjunto con otros servicios no regulados, e identificar cada servicio;</p>
<p> III.        Acreditar trimestralmente las operaciones de compraventa y las inherentes a los servicios prestados y contratados con las personas proveedoras y clientes, mediante la remisión de los comprobantes fiscales correspondientes y los demás documentos exigibles conforme a la Normatividad aplicable, y</p>
<p> IV.        Informar anualmente a la Comisión el desglose de los principales componentes de sus costos unitarios asociados a la Comercialización, incluidos la adquisición del producto, los servicios logísticos contratados, el Transporte, Almacenamiento o Distribución y los márgenes operativos estimados por contrato celebrado.</p>
<p> Las personas Permisionarias de Comercialización deben entregar, además, la información que la Secretaría, la Comisión y las demás autoridades competentes requieran para fines de supervisión y estadísticos del sector energético, en los términos y condiciones previstos en el Reglamento de la Ley del Sector Hidrocarburos y demás Normatividad aplicable.</p>
<p> La información y documentación que las personas Permisionarias de Comercialización presenten a la Comisión en cumplimiento de las presentes Disposiciones se utiliza para fines de supervisión y cumplimiento de obligaciones. La información relativa a precios, fórmulas de precios, costos, márgenes, proveedores, clientes y condiciones contractuales debe tratarse en su administración, reserva y confidencialidad, de conformidad a lo que disponga la legislación aplicable en materia de transparencia, acceso a la información y datos personales.</p>',36,'ordinario','DACG de comercialización','CAPÍTULO VII · De las Obligaciones de las personas Permisionarias de Comercialización',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('fcca877c-f4b1-501e-bb61-ee9f0700f973','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 35','<p> CAPÍTULO VIII<br/> </p>
<p> De las limitaciones a las operaciones entre personas Permisionarias de Comercialización<br/> </p>
<p> Artículo 35. Limitaciones sobre los proveedores. Las personas que obtengan un permiso de Comercialización al amparo de las Disposiciones no pueden adquirir productos de otras personas Permisionarias de Comercialización que no incluyan, como parte de su servicio, la prestación, gestión o contratación de los servicios de Transporte, Almacenamiento o Distribución. Lo anterior sin perjuicio de las excepciones previstas en el Reglamento de la Ley del Sector Hidrocarburos.</p>',37,'ordinario','DACG de comercialización','CAPÍTULO VIII · De las limitaciones a las operaciones entre personas Permisionarias de Comercialización',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('cf5fa08d-6609-5ece-9dfa-5b518c3cdf88','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 36','<p> Artículo 36. Limitaciones sobre las personas Usuarias. Las personas que obtengan un permiso de Comercialización al amparo de las Disposiciones no pueden vender sus productos a otras personas Permisionarias de Comercialización que, como parte de la prestación de los servicios de estas últimas, dirigidos a otras personas Usuarias, no incorporen algún servicio de valor agregado relacionado con las actividades reguladas por la Comisión en materia de Hidrocarburos. Lo anterior, sin perjuicio de las excepciones previstas en el Reglamento de la Ley del Sector Hidrocarburos.</p>',38,'ordinario','DACG de comercialización','CAPÍTULO VIII · De las limitaciones a las operaciones entre personas Permisionarias de Comercialización',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('fb45f07d-b073-522d-9310-854274c844a7','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 37','<p> Artículo 37. Información adicional relacionada con las limitaciones. Para efectos de evaluar los supuestos establecidos en el presente Capítulo, la Comisión puede allegarse de información adicional conforme lo dispuesto en el artículo 17 de las Disposiciones.</p>',39,'ordinario','DACG de comercialización','CAPÍTULO VIII · De las limitaciones a las operaciones entre personas Permisionarias de Comercialización',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('c12a45aa-775a-56a4-9d10-7567e8c81282','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 38','<p> CAPÍTULO IX<br/> </p>
<p> De la revocación, caducidad y suspensión<br/> </p>
<p> Artículo 38. Supuestos de Revocación de los permisos. La Comisión puede revocar los permisos de Comercialización de Gas Natural, Petrolíferos, Gas Licuado de Petróleo o Petroquímicos cuando se actualice alguna de las causales de revocación previstas en los artículos 89 y 93 de la Ley del Sector Hidrocarburos, de conformidad con los artículos 91, 109 y 329 del Reglamento de la Ley del Sector Hidrocarburos, según corresponda a la actividad, al producto y a las obligaciones de la persona Permisionaria de Comercialización, conforme a los siguientes supuestos:</p>
<p> I.          Incumplir, sin causa justificada y autorización de la autoridad competente, con el objeto, las obligaciones o las condiciones del permiso;</p>
<p> II.         Realizar prácticas indebidamente discriminatorias en perjuicio de las personas Usuarias;</p>
<p> III.        No respetar la regulación en materia de precios y tarifas, incluida la correspondiente a la contabilidad regulatoria, así como los términos y condiciones que fije la autoridad competente o las disposiciones que los regulen;</p>
<p> IV.        Ceder o gravar los permisos, los derechos que estos confieren o los bienes utilizados para su ejecución, sin la autorización de la autoridad competente;</p>
<p> V.         No otorgar o no mantener vigentes las garantías o los seguros correspondientes, incluidos los necesarios para cubrir daños a terceros, conforme a la regulación aplicable;</p>
<p> VI.        Incumplir las Normas Oficiales Mexicanas aplicables;</p>
<p> VII.       Incumplir de forma continua el pago de contribuciones y aprovechamientos por los servicios de supervisión de los permisos. Para estos efectos, el incumplimiento es continuo cuando la persona Permisionaria de Comercialización omite el pago por más de un ejercicio fiscal;</p>
<p> VIII.      Interrumpir las actividades objeto del permiso durante, al menos, treinta días naturales continuos, sin causa justificada a juicio de la Comisión;</p>
<p> IX.        No acatar las resoluciones que emita la autoridad competente en materia de competencia económica, en el ámbito de sus atribuciones;</p>
<p> X.         No acatar las resoluciones que emita la Agencia, en el ámbito de sus atribuciones;</p>
<p> XI.        Realizar actividades con Gas Natural, Petrolíferos, Gas Licuado de Petróleo o Petroquímicos que se compruebe hayan sido adquiridos de forma ilícita o mediante la comisión del delito de contrabando de dichos productos, cuando así se determine mediante resolución firme de autoridad competente, en términos de los artículos 89, fracción I, y 119, fracción V, de la Ley del Sector Hidrocarburos;</p>
<p> XII.       Incumplir la entrega de información que permita a la Secretaría o a la Comisión conocer los controles volumétricos, la medición y la calidad del Gas Natural, Petrolíferos, Gas Licuado de Petróleo o Petroquímicos objeto del permiso, las operaciones comerciales realizadas con clientes y proveedores, así como la demás información que dichas autoridades requieran para fines de supervisión y estadísticos del sector energético, en los términos del Reglamento de la Ley del Sector Hidrocarburos y demás Normatividad aplicable;</p>
<p> XIII.      No contar con los equipos y programas informáticos para llevar los controles volumétricos referidos en el artículo 119, fracción XXII, de la Ley del Sector Hidrocarburos o, contando con ellos, no mantenerlos en operación en todo momento, alterarlos, inutilizarlos o destruirlos;</p>
<p> XIV.      No contar con los controles volumétricos, en el supuesto previsto en los artículos 89, fracción XV y 119, fracción XXIII, de la Ley del Sector Hidrocarburos;</p>
<p> XV.       No generar o conservar, de manera reiterada, los reportes de información de controles volumétricos de Hidrocarburos o Petrolíferos, en el supuesto previsto en el artículo 89, fracción XVI, de la Ley del Sector Hidrocarburos;</p>
<p> XVI.      Actualizar alguno de los siguientes supuestos fiscales:</p>
<p> a)     Ubicarse en alguno de los supuestos establecidos en el artículo 69, penúltimo párrafo, del Código Fiscal de la Federación, y que el nombre, denominación o razón social y la clave en el RFC de la persona Permisionaria de Comercialización se encuentren contenidos en la publicación de la página de Internet del Servicio de Administración Tributaria a que se refiere el último párrafo del citado artículo, o</p>
<p> b)     Que la persona Permisionaria de Comercialización o alguna de sus personas socias o accionistas se encuentre publicada en definitiva en el listado previsto en el artículo 69-B, cuarto párrafo, del Código Fiscal de la Federación;</p>
<p> XVII.     Que, por causas imputables a la persona Permisionaria de Comercialización, se prevea un peligro inminente para la seguridad nacional, la seguridad energética o la economía nacional, conforme al artículo 93 de la Ley del Sector Hidrocarburos;</p>
<p> XVIII.     La falta de acreditación de la materialidad del domicilio como parte del cumplimiento de sus obligaciones, así como la imposibilidad de localizar al sujeto regulado, la inexistencia del inmueble señalado o la negativa injustificada para permitir su verificación, o</p>
<p> XIX.      Actualizar alguna de las demás causales de revocación previstas en el título de permiso respectivo.</p>
<p> Para efectos de la fracción I de este artículo, se comprende el incumplimiento de las actividades y obligaciones previstas en el artículo 109 del Reglamento de la Ley del Sector Hidrocarburos que se encuentren incorporadas en el título de permiso, en los términos del último párrafo de dicho artículo, así como el incumplimiento de los términos, condiciones y obligaciones a que se refiere el artículo 91, segundo párrafo, del Reglamento de la Ley del Sector Hidrocarburos.</p>
<p> La aplicación de las causales debe atender a los elementos y condiciones establecidos en la Ley del Sector Hidrocarburos y el Reglamento de la Ley del Sector Hidrocarburos.</p>',40,'ordinario','DACG de comercialización','CAPÍTULO IX · De la revocación, caducidad y suspensión',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('3d5a66b1-b4cd-5266-8954-9b9d8e9b49a1','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 39','<p> Artículo 39. Procedimiento de revocación. La Comisión debe sustanciar y resolver el procedimiento de revocación de los permisos de Comercialización de conformidad con los artículos 89 y 93 de la Ley del Sector Hidrocarburos y 329 del Reglamento de la Ley del Sector Hidrocarburos.</p>
<p> El procedimiento se sujeta a lo dispuesto en el artículo 93 de la Ley del Sector Hidrocarburos y, en lo no previsto, se aplica supletoriamente la Ley Federal de Procedimiento Administrativo, salvo que la Ley del Sector Hidrocarburos u otra disposición especial establezca un procedimiento específico, en cuyo caso se aplica este último.</p>',41,'ordinario','DACG de comercialización','CAPÍTULO IX · De la revocación, caducidad y suspensión',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('209f9d6a-24a3-5ba0-81f8-fb0b88947f0f','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 40','<p> Artículo 40. Supuestos de caducidad de los permisos. Los permisos de Comercialización de Gas Natural, Petrolíferos, Gas Licuado de Petróleo y Petroquímicos caducan cuando las personas Permisionarias de Comercialización se ubiquen en alguno de los supuestos previstos en el artículo 88 de la Ley del Sector Hidrocarburos, conforme a lo siguiente:</p>
<p> I.          No ejerzan los derechos conferidos en el título de permiso dentro del plazo que se establezca en este para tal efecto;</p>
<p> II.         A falta de un plazo expresamente establecido en el título de permiso, no ejerzan los derechos conferidos durante un periodo consecutivo de trescientos sesenta y cinco días naturales, o</p>
<p> III.        Se ubiquen en alguno de los demás supuestos de caducidad previstos en el título de permiso respectivo.</p>
<p> La actualización de cualquiera de estos supuestos debe ser determinada por la Comisión mediante la declaratoria correspondiente, previa garantía de audiencia.</p>
<p> La Comisión, en los permisos que emita a partir de la entrada en vigor de las Disposiciones, debe establecer en los títulos correspondientes que estos caducan en un plazo de ciento ochenta días naturales contados a partir de que se emitan o de que se realice la última operación comercial y no se acredite haber formalizado alguna oferta en dicho plazo.</p>',42,'ordinario','DACG de comercialización','CAPÍTULO IX · De la revocación, caducidad y suspensión',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('b17c3906-0d73-51af-a1c4-a7eecbe7ac8a','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 41','<p> Artículo 41. Procedimiento de caducidad. La Comisión debe sustanciar y resolver el procedimiento para declarar la caducidad de los permisos de Comercialización de conformidad con lo establecido en la Normatividad que emita la Comisión.</p>',43,'ordinario','DACG de comercialización','CAPÍTULO IX · De la revocación, caducidad y suspensión',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('8b5545a0-5abe-588f-a9da-62f5c3d1e942','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 42','<p> Artículo 42. Autorización para la suspensión de los servicios, salvo por causa de caso fortuito o fuerza mayor. La persona Permisionaria de Comercialización puede suspender los servicios o actividades previa autorización de la Comisión, en términos del artículo 119, fracción XII de la Ley del Sector Hidrocarburos. Sin perjuicio de lo anterior, dicha persona Permisionaria de Comercialización no incurre en responsabilidad por suspensión del servicio o actividad, cuando esta se origine por caso fortuito o fuerza mayor en términos del artículo 174 del Reglamento de la Ley del Sector Hidrocarburos.</p>
<p> Asimismo, la Comisión puede ejercer la suspensión provisional del permiso de Comercialización cuando se incurra en alguno de los supuestos previstos en el artículo 79 de la Ley del Sector Hidrocarburos.</p>
<p> La persona Permisionaria de Comercialización que requiera solicitar la autorización de suspensión del permiso de Comercialización debe presentar los siguientes requisitos ante la Comisión y de conformidad con el Anexo VII de las Disposiciones:</p>
<p> I.          Número de permiso de Comercialización;</p>
<p> II.         Nombre, denominación o razón social;</p>
<p> III.        RFC;</p>
<p> IV.        Domicilio para oír y recibir notificaciones;</p>
<p> V.         Nombre del representante o apoderado legal;</p>
<p> VI.        Documento que acredite la representación legal de la persona Permisionaria de Comercialización;</p>
<p> VII.       Solicitud expresa para suspender las actividades del permiso de Comercialización;</p>
<p> VIII.      Fecha a partir de la cual se efectúa la suspensión del servicio;</p>
<p> IX.        Razones que originan la solicitud de suspensión del servicio;</p>
<p> X.         Fecha de reanudación del servicio, y</p>
<p> XI.        Firma electrónica.</p>
<p> Las personas Permisionarias de Comercialización que presenten una solicitud de suspensión de su permiso de Comercialización no deben suspender actividades sin la autorización de la Comisión.</p>',44,'ordinario','DACG de comercialización','CAPÍTULO IX · De la revocación, caducidad y suspensión',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('a49ddbc8-b5dd-5cac-9f7a-f83ceef1d34f','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 43','<p> Artículo 43. Procedimiento de suspensión. La Comisión debe sustanciar y resolver el procedimiento para autorizar la suspensión del permiso de Comercialización de conformidad con lo establecido en el artículo 17 de la Ley Federal de Procedimiento Administrativo.</p>',45,'ordinario','DACG de comercialización','CAPÍTULO IX · De la revocación, caducidad y suspensión',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('eacc74b7-8b87-5ebc-8c5c-d247586e52c8','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 44','<p> Artículo 44. Supuestos de terminación anticipada del permiso. La persona Permisionaria de Comercialización puede terminar de manera anticipada el permiso de Comercialización otorgado, previa autorización de la Comisión, en términos del artículo 87, fracción II de la Ley del Sector Hidrocarburos, para lo cual debe presentar los siguientes requisitos ante la Comisión y de conformidad con el Anexo VIII de las Disposiciones:</p>
<p> I.          Número de permiso de Comercialización;</p>
<p> II.         Nombre, denominación o razón social;</p>
<p> III.        RFC;</p>
<p> IV.        Domicilio para oír y recibir notificaciones;</p>
<p> V.         Nombre del representante o apoderado legal;</p>
<p> VI.        Documento que acredite la representación legal de la persona Permisionaria de Comercialización;</p>
<p> VII.       Razones que originan la solicitud de terminación anticipada del permiso;</p>
<p> VIII.      Manifestación bajo protesta de decir verdad que se encuentra al corriente en el cumplimiento de todas sus obligaciones derivadas del permiso y que no hay afectaciones a terceros, y</p>
<p> IX         Firma electrónica.</p>
<p> La terminación del permiso no exime a su titular de las obligaciones contraídas durante su vigencia, con el Gobierno Federal y con terceros.</p>',46,'ordinario','DACG de comercialización','CAPÍTULO IX · De la revocación, caducidad y suspensión',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('96c98abb-d5ef-5767-8ac2-baa6d3e143f9','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 45','<p> Artículo 45. Procedimiento de terminación anticipada del permiso. La Comisión debe sustanciar y resolver el procedimiento para autorizar la terminación del permiso de Comercialización de conformidad con lo establecido en el artículo 17 de la Ley Federal de Procedimiento Administrativo.</p>',47,'ordinario','DACG de comercialización','CAPÍTULO IX · De la revocación, caducidad y suspensión',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('bae45440-3779-5136-a7a7-ed9791574058','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 46','<p> CAPÍTULO X<br/> </p>
<p> De la verificación y sanciones<br/> </p>
<p> Artículo 46. Verificación. La Comisión debe ejercer sus atribuciones de verificación sobre el cumplimiento de las obligaciones establecidas para las personas Permisionarias de Comercialización, referidas en los Capítulos VII y X de las Disposiciones, conforme a los mecanismos establecidos en el artículo 262 del Reglamento de la Ley del Sector Hidrocarburos, mediante visitas de verificación, requerimientos de información, documentación, informes y comparecencias.</p>',48,'ordinario','DACG de comercialización','CAPÍTULO X · De la verificación y sanciones',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('3eafa2bc-2165-5f72-8e7c-81c761f77fd0','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 47','<p> Artículo 47. Sanciones por incumplimiento. Cuando las personas Permisionarias de Comercialización no cumplan con las obligaciones señaladas en las Disposiciones, deben ser acreedoras a la sanción correspondiente de conformidad con los artículos 121, fracciones II, incisos a), b), d), f), h), i), j) y l), y III, incisos b) y c), y 123 de la Ley del Sector Hidrocarburos, sin perjuicio de las causales de revocación previstas en estas Disposiciones, de conformidad con el artículo 89 de dicha Ley y de las demás consecuencias previstas en la Normatividad aplicable.</p>',49,'ordinario','DACG de comercialización','CAPÍTULO X · De la verificación y sanciones',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('a752a976-cbf1-5f28-9cfc-7dcf7614df7f','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 48','<p> Artículo 48. Del inicio de operaciones. Para dar cumplimiento a lo establecido en el artículo 33, fracción IV de las Disposiciones, en términos del artículo 109, quinto párrafo del Reglamento de la Ley del Sector Hidrocarburos, la persona Permisionaria de Comercialización debe notificar a la Comisión el inicio de sus operaciones amparadas con al menos 20 días hábiles previos al mismo, incluyendo la siguiente información, conforme al Anexo IX de las Disposiciones:</p>
<p> I.          Número de permiso de Comercialización;</p>
<p> II.         Nombre, denominación o razón social;</p>
<p> III.        RFC;</p>
<p> IV.        Fecha en la que se remitió el modelo de contrato a través de aviso a la Comisión;</p>
<p> V.         Fecha programada para iniciar operaciones;</p>
<p> VI.        Manifestaciones y autorizaciones:</p>
<p> a)    Manifestación bajo protesta de decir verdad que la persona Permisionaria de Comercialización cuenta con las garantías y seguros que respaldan la actividad de Comercialización y se compromete a mantenerlas vigentes durante la vigencia del permiso;</p>
<p> b)    Manifestación bajo protesta de decir verdad que la información, datos y documentación que se presentan y acompañan al presente trámite son verídicos, auténticos y fidedignos, y</p>
<p> c)     Autorización para que la información proporcionada sea utilizada por la Secretaría de Energía, la Comisión y la Agencia Nacional de Seguridad Industrial y Protección al Medio Ambiente del Sector Hidrocarburos, y</p>
<p> VII.       Firma electrónica.</p>',50,'ordinario','DACG de comercialización','CAPÍTULO X · De la verificación y sanciones',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('e13cb0ec-79fd-589a-ad9f-2534a5ce81f2','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 49','<p> CAPÍTULO XI<br/> </p>
<p> De los Contratos de Comercialización<br/> </p>
<p> Artículo 49. Contenido mínimo. De conformidad con el artículo 173 del Reglamento de la Ley del Sector Hidrocarburos y, para efectos de asegurar la Trazabilidad del Gas Natural, Petrolíferos, Gas Licuado de Petróleo y Petroquímicos objeto de la Comercialización, los contratos de Comercialización deben permitir identificar y acreditar, de manera verificable, la procedencia, los movimientos, el volumen, las características de la calidad, los puntos de entrega y recepción y el destino del producto, así como contemplar, al menos, los elementos siguientes:</p>
<p> I.          Generales: la identificación de las partes y del permiso vigente de cada una, el objeto, las definiciones de los términos utilizados en el contrato que resulten necesarios para su interpretación y ejecución, sin perjuicio de las definiciones previstas en la Ley, el Reglamento y la Normatividad aplicable, la vigencia, el plazo, las obligaciones de cada una de las partes, las responsabilidades, las condiciones especiales que, en su caso, se pacten y los mecanismos para la solución de controversias;</p>
<p> II.         Licitud y origen del producto:</p>
<p> a)    La declaración sobre el origen lícito del producto, con el nombre de quien lo suministra y el número de permiso, y la precisión de si el producto es nacional o de importación;</p>
<p> b)    La denominación y especificaciones del producto y, tratándose de Petrolíferos, como las gasolinas y el diésel, su marca comercial registrada ante la Comisión;</p>
<p> c)     La declaración de que las partes se obligan a cumplir con la Normatividad aplicable en materia de anticorrupción, así como de que no se realizan operaciones con recursos de procedencia ilícita, ni derivadas de actos de corrupción, y de que la actividad económica se vincula con la actividad permisionada;</p>
<p> d)    Tratándose de personas Usuarias Finales, la declaración del destino y uso del producto, y el compromiso de no comercializarlo a terceros sin el permiso que corresponda;</p>
<p> e)    La declaración de que las partes conocen, aceptan y se obligan a cumplir la Ley del Sector Hidrocarburos, el Reglamento de la Ley del Sector Hidrocarburos y la Normatividad aplicable a las actividades objeto del contrato, y</p>
<p> f)     La declaración de que las partes cuentan con los permisos y autorizaciones gubernamentales necesarios para la realización de las actividades objeto del contrato y se obligan a mantenerlos vigentes durante su ejecución.</p>
<p> III.        Volumen y entrega: el volumen contractual o su mecanismo de determinación; el procedimiento para formular, confirmar y modificar los pedidos; la modalidad de entrega y los puntos de entrega y recepción; la transmisión de la propiedad y del riesgo; y la medición conforme a la Normatividad aplicable, con indicación del sistema y del punto donde se realiza;</p>
<p> IV.        Calidad y ruta logística:</p>
<p> a)    Las especificaciones de calidad conforme a la Normatividad aplicable, el mecanismo de verificación y de atención de inconformidades, y los sistemas de marcaje del producto cuando aquella los prevea;</p>
<p> b)    Los servicios de Transporte, Almacenamiento o Distribución, y de valor agregado incluidos, la parte que los contrata y el prestador de servicios, con el número de permiso vigente de este último, cuando aplique;</p>
<p> c)     La responsabilidad de custodia del producto durante la ruta, y</p>
<p> d)    La obligación de informar de inmediato a la otra parte y a la Comisión, cualquier circunstancia que impida el suministro;</p>
<p> V.         Trazabilidad documental:</p>
<p> a)    La documentación que ampare cada entrega, la cual debe identificar al proveedor, el producto, el volumen y su unidad de medida, los puntos de entrega y recepción y el destino, así como, cuando resulte aplicable, los movimientos realizados para su entrega;</p>
<p> b)    La obligación de reflejar en el contrato, sus anexos, órdenes de suministro, confirmaciones de transacción o documentos equivalentes, según corresponda, cualquier cambio de proveedor, origen, producto, marca en el caso de gasolinas y diésel y con excepción de Gas Licuado de Petróleo, volumen, puntos de entrega y recepción o destino final, así como de actualizar en el Formulario de Contratos, conforme a este Capítulo, únicamente las modificaciones al contrato relativas a dichos elementos o a los volúmenes contractuales mínimo y máximo, y</p>
<p> c)     La conservación de la documentación que permita acreditar la Trazabilidad del producto durante el plazo establecido en la Normatividad aplicable y su entrega a la Comisión cuando esta la requiera;</p>
<p> VI.        Precio y contraprestaciones: el precio o su fórmula, desglosado entre el producto y los servicios contratados, en términos que permitan informar los costos unitarios a que se refiere el artículo 109, fracción IX, del Reglamento de la Ley del Sector Hidrocarburos; los ajustes por diferencias de medición o calidad; las bonificaciones y, en su caso, las penalizaciones; la facturación, el plazo y la forma de pago, así como la sujeción a los precios máximos que establezca la autoridad competente, cuando resulte aplicable, y</p>
<p> VII.       Responsabilidades y obligaciones:</p>
<p> a)    La obligación de permitir y facilitar las visitas de verificación practicadas por la Comisión, así como cualquier otro medio de verificación que la Comisión lleve a cabo en el ejercicio de sus atribuciones;</p>
<p> b)    Las causas, procedimiento y efectos de la suspensión del servicio, incluyendo los supuestos en los que resulte necesario suspender temporalmente el suministro o la prestación de los servicios contratados para verificar o corregir incumplimientos relacionados con la licitud, Trazabilidad, calidad, medición o vigencia de los permisos correspondientes;</p>
<p> c)     Las causas de la Terminación anticipada del Contrato tales como la falta de acreditación del origen lícito, el incumplimiento de las obligaciones de Trazabilidad y la pérdida de vigencia del permiso necesario para la ejecución del contrato.</p>
<p>        La parte que no dé origen a las causas de la terminación anticipada no se encuentra sujeta a penalización;</p>
<p> d)    La cesión solo a favor de personas que cuenten con el permiso que corresponda, con aviso previo a la Comisión;</p>
<p> e)    Los supuestos de procedencia para la modificación del contrato;</p>
<p> f)     La prohibición de pactar cláusulas que impidan cumplir obligaciones frente a la Comisión o contravengan las disposiciones previstas en la Ley Federal de Competencia Económica, y</p>
<p> g)    Los supuestos de caso fortuito o fuerza mayor, así como sus efectos en el cumplimiento de las obligaciones contractuales, incluida, en su caso, la suspensión temporal del suministro o de la prestación de los servicios contratados.</p>
<p> El contrato debe ajustarse al contenido mínimo previsto en el presente artículo y conforme al modelo de contrato que para tal efecto establezca la Comisión en su página electrónica. Cualquier estipulación adicional que las partes pretendan convenir y que no se encuentre prevista en el presente artículo o en el modelo de contrato debe ser congruente con estos y no debe contravenir lo establecido en las presentes Disposiciones, la Ley del Sector Hidrocarburos, su Reglamento ni la demás Normatividad aplicable.</p>',51,'ordinario','DACG de comercialización','CAPÍTULO XI · De los Contratos de Comercialización',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('a53da1a1-77fb-5c05-bb69-b7e730eeae27','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 50','<p> Artículo 50. Registro. Las personas Permisionarias de Comercialización, en cumplimiento del artículo 109, fracciones I, III, IV, V, VI y VII del Reglamento de la Ley del Sector Hidrocarburos, deben registrar los contratos que celebren con sus proveedores y clientes, sean estos Permisionarias o Usuarias Finales, a través del Formulario de Contratos, a fin de garantizar la Trazabilidad del producto comercializado.</p>
<p> La estructura, los campos, los catálogos y las opciones del Formulario de Contratos se establecen en el Anexo X, que forma parte integrante de estas Disposiciones. La información registrada tiene por objeto vincular cada transacción de compra o venta con el contrato que la respalda, identificando el producto, su marca y la otra parte.</p>
<p> El registro comprende los contratos siguientes, los cuales deben señalar expresamente su vigencia:</p>
<p> I.          Aquellos mediante los cuales se gestionen los servicios de Transporte, Almacenamiento o Distribución;</p>
<p> II.         Los que acrediten el inventario de los productos a comercializar;</p>
<p> III.        Aquellos que sean suscritos con proveedores que acrediten el suministro y confirmen la procedencia lícita del producto a comercializar, y</p>
<p> IV.        Los suscritos con clientes y los que permitan acreditar la relación comercial con los proveedores y clientes inicialmente declarados, incluyendo los volúmenes comprometidos y el destino final del producto.</p>
<p> El registro se debe realizar por cada contrato que se suscriba en los periodos de enero a junio y de julio a diciembre de cada año calendario. Los contratos deben quedar registrados a más tardar dentro de los diez días hábiles siguientes a la conclusión del semestre correspondiente, sin perjuicio de los demás plazos previstos en los artículos 51 y 52 de estas Disposiciones. La información debe presentarse exclusivamente a través del Formulario de Contratos, dentro de los diez días hábiles siguientes a la conclusión de cada semestre. El Formulario permanece habilitado durante cada semestre para que las personas Permisionarias de Comercialización y sus contrapartes registren, validen y actualicen los contratos correspondientes.</p>
<p> El vencimiento de la vigencia del permiso no exime del registro de los contratos correspondientes al periodo en que ocurra dicho vencimiento.</p>
<p> Lo previsto en este Capítulo no sustituye la presentación de los contratos formalizados a que se refiere el artículo 108 del Reglamento de la Ley del Sector Hidrocarburos.</p>
<p> Las personas Permisionarias de Comercialización son responsables de la información que se registra en el Formulario de Contratos, por lo que se entiende que esta es fidedigna y corresponde a la que se encuentra en los contratos que suscriban en el ejercicio de sus actividades.</p>
<p> La Comisión puede publicar en su página electrónica guías que contengan la estructura, los campos, los catálogos y el procedimiento para llenar el Formulario de Contratos. La Comisión puede actualizar los aspectos operativos, tales como pantallas y rutas de navegación, sin modificar las obligaciones, los plazos, ni los campos del Formulario de Contratos, mediante su publicación en la Oficialía de Partes Electrónica y en su página electrónica.</p>',52,'ordinario','DACG de comercialización','CAPÍTULO XI · De los Contratos de Comercialización',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('b5793100-012c-5731-9ba5-467880a25a13','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 51','<p> Artículo 51. Validación, modificación y terminación de los contratos entre personas Permisionarias de Comercialización. Cuando los contratos señalados en el artículo anterior se suscriban entre personas Permisionarias de Comercialización, cualquiera de las partes puede realizar su registro mediante el Formulario de Contratos, mientras que la otra parte únicamente debe validar el registro realizado. Por lo que el registro realizado por una de las partes y la validación de la otra dan por cumplida la obligación de registro para ambas.</p>
<p> Para realizar el registro señalado en el párrafo anterior, las personas Permisionarias de Comercialización que suscriban contratos entre sí, deben seguir el siguiente procedimiento:</p>
<p> I.          La persona Permisionaria de Comercialización que realice el registro de los contratos, en lo sucesivo, la persona responsable del registro, debe completar el Formulario de Contratos ingresando a la Oficialía de Partes Electrónica. Una vez que concluya el registro, el Formulario de Contratos le asigna el ContratoId y el estatus "Registrado";</p>
<p> II.         La Comisión, mediante la Oficialía de Partes Electrónica y de manera automática, debe notificar dicho registro a la contraparte del contrato que se registra;</p>
<p> III.        La contraparte del contrato que se registra debe aceptar o rechazar el registro, señalando, en este último caso, el motivo del rechazo, mediante la validación electrónica del Formulario de Contratos a través de la Oficialía de Partes Electrónica. La validación consiste en confirmar que la información registrada corresponde al contrato celebrado. Lo anterior, en un plazo no mayor a diez días hábiles contados a partir del día hábil siguiente en que surta efectos la notificación que corresponda.</p>
<p>             Si la contraparte rechaza el registro del contrato, se le notifica de manera automática a través de la Oficialía de Partes Electrónica a la persona responsable del registro, que debe revisar la información y, por única ocasión, realizar las adecuaciones que correspondan y someter nuevamente a validación de su contraparte el registro del contrato, ello, en un plazo máximo de diez días hábiles contados a partir de que surta efectos la notificación del rechazo correspondiente.</p>
<p>             Cuando la contraparte reciba nuevamente la solicitud de validación del registro del contrato que corresponda, por única ocasión, cuenta nuevamente con un plazo máximo de diez días hábiles para aceptar o rechazar el registro, en términos de la fracción III de este artículo, y</p>
<p> IV.        Una vez que la contraparte del contrato registrado haya validado el registro, se considera que el contrato queda registrado para ambas Permisionarias ante la Comisión, sin necesidad de un registro independiente, por lo que se le asigna el estatus de "Aceptado". En caso de que la contraparte rechace el registro, se le debe asignar el estatus de "Rechazado".</p>
<p> El Formulario de Contratos genera, en formato PDF, el acuse de registro o la notificación de rechazo, según corresponda, que pueden consultarse y descargarse en cualquier momento a través de la Oficialía de Partes Electrónica.</p>
<p> El estatus de "Aceptado" acredita que ante la Comisión se cumplió con la obligación de registrar los contratos que correspondan, en tanto que el estatus de "Rechazado", una vez vencido el plazo para su corrección, no puede considerarse como cumplimiento de la obligación de registro de los contratos que correspondan.</p>
<p> Si la contraparte no acepta ni rechaza el registro dentro del plazo previsto en la fracción III, el contrato conserva el estatus "Registrado" hasta su validación. En este caso, el acuse de registro acredita el cumplimiento de la persona responsable del registro y la omisión de validar constituye un incumplimiento imputable únicamente a la contraparte, que puede sancionarse conforme a la Normatividad aplicable.</p>
<p> El Formulario de Contratos no admite un segundo registro del mismo contrato. Si ninguna de las partes realiza el registro, ambas incumplen la obligación prevista en el artículo 50 anterior.</p>
<p> Si durante la vigencia del contrato registrado este se modifica, la persona Permisionaria de Comercialización responsable del registro original debe actualizar la información en el Formulario de Contratos dentro de los cinco días hábiles siguientes a la formalización de la modificación realizada, de conformidad con el artículo 109, sexto párrafo, del Reglamento de la Ley del Sector Hidrocarburos, y debe anexar la documentación que soporte la modificación correspondiente. La modificación del contrato no constituye un nuevo registro, por lo que conserva el ContratoId asignado originalmente y se sujeta a la validación electrónica de la otra parte, en los términos de este artículo.</p>
<p> La persona responsable del registro debe informar la Terminación anticipada del Contrato en el Formulario de Contratos dentro de los diez días hábiles siguientes a que se formalice, con el comprobante que la acredite, el cual queda vinculado al ContratoId original. La Terminación anticipada está sujeta a validación electrónica de la otra parte, en los términos de este artículo, y una vez aceptada se asigna al contrato el estatus "Finalizado".</p>
<p> Al concluir la vigencia del contrato, la persona responsable del registro debe registrar su finalización en el Formulario de Contratos dentro de los diez días hábiles siguientes, bajo protesta de decir verdad, conforme al Anexo XI de estas Disposiciones, sin que se requiera validación de la otra parte, y se asigna al contrato el estatus "Finalizado".</p>
<p> En cada caso, a través del Formulario de Contratos se genera el acuse correspondiente en formato PDF.</p>',53,'ordinario','DACG de comercialización','CAPÍTULO XI · De los Contratos de Comercialización',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('ade0657a-d402-50e9-b272-24c9d98b26f9','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 52','<p> Artículo 52. Validación, modificación y terminación de los contratos con personas Usuarias Finales o Permisionarias de actividades distintas a la Comercialización. Los contratos suscritos con personas Usuarias Finales o con Permisionarias de actividades distintas a la Comercialización se validan de forma automática.</p>
<p> La persona Permisionaria de Comercialización debe registrar a través del Formulario de Contratos, los contratos que correspondan. Una vez realizado el registro, el Formulario de Contratos le asigna el ContratoId, así como el estatus de "Aceptado", con lo que se acredita el cumplimiento de la obligación de registrar sus contratos.</p>
<p> El Formulario de Contratos genera, en formato PDF, el acuse de registro, según corresponda, que puede consultarse y descargarse en cualquier momento a través de la Oficialía de Partes Electrónica.</p>
<p> La modificación, la Terminación anticipada y la finalización de estos contratos se registran en los plazos y con la documentación previstos en el artículo 51 anterior, conservan el ContratoId asignado originalmente y se validan de forma automática.</p>',54,'ordinario','DACG de comercialización','CAPÍTULO XI · De los Contratos de Comercialización',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('e6ebfc0a-723a-59a0-954f-e6e512f508eb','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 53','<p> Artículo 53. Trazabilidad y revisión de la información. La persona Permisionaria de Comercialización debe declarar el ContratoId en cada transacción que reporte a los sistemas de información de la Comisión, a efecto de vincular la información reportada con el contrato que la respalda y con la documentación que acredite el origen lícito, la disponibilidad y la Trazabilidad de los productos, de conformidad con lo previsto en el artículo 5 de las presentes Disposiciones. Asimismo, debe declarar la marca comercial que corresponda, cuando resulte aplicable, e identificar la ruta comercial del producto desde su origen hasta su expendio al público o consumo final.</p>
<p> Las transacciones realizadas entre la fecha de suscripción del contrato y la de su registro deben vincularse con el ContratoId correspondiente una vez generado, en el reporte inmediato siguiente que se presente a los sistemas de información de la Comisión.</p>
<p> La persona Permisionaria de Comercialización debe conservar y respaldar la información y documentación relacionada con los contratos registrados y las transacciones reportadas a través del Formulario de Contratos, de manera que permita verificar la correspondencia documental y volumétrica de los productos comercializados, durante la vigencia de su permiso y por un periodo de diez años posteriores a su conclusión, sin perjuicio de las demás obligaciones de conservación previstas en el artículo 49 del Código de Comercio y demás disposiciones jurídicas aplicables.</p>
<p> La Comisión puede requerir, en cualquier momento, a la persona Permisionaria de Comercialización responsable del registro o a la otra parte del contrato, la información y documentación necesaria para verificar la calidad, integridad y veracidad de la información reportada, así como el origen lícito, la disponibilidad y la Trazabilidad de los productos comercializados, incluso mediante manifestación bajo protesta de decir verdad, de conformidad con los artículos 116, fracción III, y 119, fracciones XX y XXI, de la Ley del Sector Hidrocarburos y 161 de su Reglamento.</p>',55,'ordinario','DACG de comercialización','CAPÍTULO XI · De los Contratos de Comercialización',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('8ff911ce-62de-5405-ac40-da6fec725cce','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Artículo 54','<p> Artículo 54. Presentación y modificación de los modelos de contrato. La presentación del modelo de contrato y de sus posteriores modificaciones, se realiza conforme a lo siguiente:</p>
<p> I.          Las Personas solicitantes que obtengan el permiso de Comercialización deben presentar modelos de contratos ante la Comisión de manera previa a la obtención del permiso que corresponda, dado que este se revisa durante el procedimiento de evaluación y resolución  de la solicitud;</p>
<p> II.         Las personas Permisionarias de Comercialización que no hayan iniciado operaciones deben presentar su modelo de contrato conforme a las presentes Disposiciones ante la Comisión mediante aviso presentado ante la Comisión, previo a iniciar operaciones, y</p>
<p> III.        Las personas Permisionarias de Comercialización que modifiquen los modelos de contratos presentados ante la Comisión bajo los supuestos previstos en las fracciones I y II del presente artículo deben notificarlo a la propia Comisión, mediante la presentación de un aviso, dentro de los primeros diez días hábiles posteriores a la formalización de la modificación que corresponda.</p>
<p> La Comisión debe emitir un acuse sobre los avisos señalados en este artículo y, en cualquier momento, puede requerir ajustes al modelo de contrato, cuando identifique inconsistencias respecto a lo establecido en las presentes Disposiciones.</p>',56,'ordinario','DACG de comercialización','CAPÍTULO XI · De los Contratos de Comercialización',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('7d06638d-646d-59d7-9ac1-d3adef1ad400','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Transitorio primero','<p> TRANSITORIOS<br/> </p>
<p> PRIMERO. Las presentes Disposiciones Administrativas de Carácter General entran en vigor al siguiente día de su publicación en el Diario Oficial de la Federación.</p>',57,'transitorio','DACG de comercialización','Transitorios',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('299485be-928d-5a93-b123-2fc79cd02348','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Transitorio segundo','<p> SEGUNDO. Se derogan todas aquellas disposiciones normativas que se opongan al presente instrumento.</p>',58,'transitorio','DACG de comercialización','Transitorios',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('33d89f5c-a120-532a-be1c-4a5c624b6d76','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Transitorio tercero','<p> TERCERO. Los permisos de Comercialización otorgados con anterioridad a la entrada en vigor del presente Acuerdo conservan su vigencia en los términos otorgados, sin perjuicio del cumplimiento de las obligaciones aplicables a la ejecución de la actividad permisionada conforme a la Ley del Sector Hidrocarburos, su Reglamento, las presentes Disposiciones y demás Normatividad aplicable.</p>',59,'transitorio','DACG de comercialización','Transitorios',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('d7ffe740-69a5-5db2-8f06-d56cc522af2c','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Transitorio cuarto','<p> CUARTO. Las solicitudes de otorgamiento de permisos de Comercialización presentadas con anterioridad a la entrada en vigor de las presentes Disposiciones y pendientes de resolución, se tramitan y resuelven conforme a las disposiciones aplicables al momento de su presentación, con observancia de los regímenes transitorios de la Ley del Sector Hidrocarburos y de su Reglamento.</p>
<p> Cuando la resolución del trámite de dichas solicitudes resulte en el otorgamiento de un permiso de Comercialización, su emisión, supervisión y verificación debe regularse de conformidad con lo establecido en la Ley del Sector Hidrocarburos, el Reglamento de la Ley del Sector Hidrocarburos y las presentes Disposiciones.</p>
<p> La entrada en vigor del presente Acuerdo no obliga a presentar nuevamente las solicitudes, a sustituir los formatos utilizados válidamente ni a repetir el pago de los derechos o aprovechamientos correspondientes. Los requerimientos y prevenciones se sujetan a las disposiciones aplicables a cada procedimiento.</p>',60,'transitorio','DACG de comercialización','Transitorios',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('a576731c-13d5-5bb8-8577-e89d796914b6','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Transitorio quinto','<p> QUINTO. La Comisión debe poner a disposición de las Personas solicitantes y personas Permisionarias de Comercialización, a partir de la entrada en vigor de las presentes Disposiciones, los formatos aprobados mediante este instrumento y los medios electrónicos necesarios para su presentación.</p>
<p> La falta de habilitación de una funcionalidad específica no constituye, por sí misma, motivo de rechazo de una promoción presentada por el medio señalado en el párrafo anterior, ni exime del cumplimiento de los requisitos y plazos aplicables.</p>',61,'transitorio','DACG de comercialización','Transitorios',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('984a9f1e-7efb-58d9-a09f-2290c785868b','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Transitorio sexto','<p> SEXTO. Las personas Permisionarias de Comercialización cuentan con un plazo de noventa días naturales, posteriores a la publicación de las presentes Disposiciones, para implementar los sistemas y procedimientos necesarios que les permitan acceder a la Oficialía de Partes Electrónica, o la que la reemplace, para dar cumplimiento a las obligaciones establecidas en este instrumento normativo. Transcurrido este plazo, las personas Permisionarias de Comercialización deben cumplir con sus obligaciones mediante la Oficialía de Partes Electrónica.</p>',62,'transitorio','DACG de comercialización','Transitorios',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('2cc681cf-8174-5de9-b9df-2c33b18c3a54','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Transitorio séptimo','<p> SÉPTIMO. Una vez concluido el plazo previsto en el Transitorio Sexto, las personas Permisionarias de Comercialización deben realizar un reporte correspondiente al primer semestre del año en curso a la fecha de publicación de las presentes Disposiciones dentro de un plazo no mayor a los primeros diez días hábiles siguientes del semestre a reportar.</p>',63,'transitorio','DACG de comercialización','Transitorios',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('97f03759-59e0-5dd5-8c6b-b999a558ab8a','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Transitorio octavo','<p> OCTAVO. Las personas Permisionarias de Comercialización a las que les fue otorgado un permiso de Comercialización por la entonces Comisión Reguladora de Energía o la Comisión Nacional de Energía, cuentan con un plazo de ciento ochenta días naturales contados a partir de la entrada en vigor de las presentes Disposiciones, para presentar la información y documentación que acredite la capacidad para importar, producir, formular o adquirir los productos comercializados en territorio nacional, así como aquella que acredite las gestiones de los servicios de Transporte, Almacenamiento o Distribución, necesarios para sus actividades, esto último, en términos de lo previsto en el artículo 5, fracción IV de las presentes Disposiciones.</p>',64,'transitorio','DACG de comercialización','Transitorios',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('1ebba1ed-7390-5f3d-982c-7efcecbeb14b','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Transitorio noveno','<p> NOVENO. Las obligaciones previstas en las presentes Disposiciones en materia de marcas comerciales, deben ser exigibles en términos de lo establecido en la regulación que emita la Comisión Nacional de Energía para tal efecto.</p>',65,'transitorio','DACG de comercialización','Transitorios',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('09ce69ff-271b-569c-a0f7-6b56f9a3f89a','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Transitorio décimo','<p> DÉCIMO. La Comisión Nacional de Energía debe publicar en el Diario Oficial de la Federación el modelo de contrato al que se refieren los artículos 49 y 50 de las presentes Disposiciones, dentro de un plazo no mayor a ciento ochenta días naturales contados a partir de la entrada en vigor de las presentes Disposiciones.</p>
<p> Hasta en tanto se realice la publicación a que se refiere el párrafo anterior, los contratos que se suscriban durante dicho periodo por las personas Permisionarias de Comercialización deben cumplir con los elementos mínimos previstos en las presentes Disposiciones.</p>
<p> Las personas que cuenten con un permiso de Comercialización vigente previo a la entrada en vigor de estas Disposiciones, conservan la validez de los modelos de Contrato previamente presentados o aprobados.</p>
<p> Aquellas personas Permisionarias de Comercialización que, al momento de la entrada en vigor de las presentes Disposiciones, no hayan presentado a cabalidad la información a la que se refiere el artículo Vigésimo transitorio del Reglamento de la Ley del Sector Hidrocarburos, cuentan con un plazo de hasta treinta días hábiles para remitir la información señalada en dicho artículo. Para efecto del cumplimiento de las obligaciones vinculadas con la presentación de los contratos a que se refiere la fracción II del artículo transitorio señalado, la información debe presentarse en los términos previstos en el Formulario de Contratos contenido en el Anexo XI.</p>',66,'transitorio','DACG de comercialización','Transitorios',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('4872897d-798b-5d43-8ea9-82f9bb36a2c9','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Transitorio décimo primero','<p> DÉCIMO PRIMERO. Las personas Permisionarias de Comercialización que sean también titulares de permisos de Transporte o Almacenamiento, o pertenezcan a un grupo de interés económico en el que otra persona permisionaria sea titular de dichos permisos, y con ello se ubiquen en el supuesto de participación cruzada a que se refieren los artículos 118 de la Ley del Sector Hidrocarburos y 109, fracción VIII, del Reglamento de la Ley del Sector Hidrocarburos, deben dar aviso a la Comisión, a través de la Oficialía de Partes Electrónica, dentro de los treinta días hábiles siguientes a la entrada en vigor de las presentes Disposiciones, a efecto de dar cumplimiento a lo previsto en el artículo 5, fracción IV, segundo párrafo de las presentes Disposiciones.</p>
<p> El aviso debe incluir el número de cada uno de los permisos de los que sean titulares, actividad y modalidad, así como los Sistemas o instalaciones a los que correspondan, conforme al Anexo X de estas Disposiciones. Tratándose de grupos de interés económico, deben señalar además la denominación o razón social de cada persona permisionaria que lo integra.</p>
<p> Recibido el aviso, la Comisión debe realizar el análisis correspondiente conforme a las atribuciones conferidas en el Décimo Primero Transitorio del Reglamento de la Ley del Sector Hidrocarburos.</p>
<p> La Comisión puede requerir mediante oficio a la persona Permisionaria, la presentación de la solicitud de autorización de participación cruzada, conforme al Acuerdo número A/005/2016, Acuerdo por el que la Comisión Reguladora de Energía interpreta para efectos administrativos la participación cruzada a la que hace referencia el segundo párrafo del artículo 83 de la Ley de Hidrocarburos y establece el procedimiento para autorizarla.</p>
<p> La persona Permisionaria debe presentar la solicitud de participación cruzada a que se refiere el párrafo anterior, dentro de los tres meses siguientes a que surta efectos la notificación del oficio.</p>
<p> La omisión del aviso o de la presentación de la solicitud en los plazos señalados se sujeta a lo previsto en los artículos 198 del Reglamento de la Ley del Sector Hidrocarburos y el Considerando Decimoctavo del Acuerdo A/005/2016.</p>
<p> Lo previsto en este transitorio no es aplicable al Grupo de Interés Económico del que formen parte las empresas públicas del Estado, en términos del último párrafo del artículo 118 de la Ley del Sector Hidrocarburos.</p>',67,'transitorio','DACG de comercialización','Transitorios',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('3331bf82-79dd-5ca3-95f3-11677a8765f9','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Transitorio décimo segundo','<p> DÉCIMO SEGUNDO. Las personas que realicen actividades de Transporte por medios distintos a ductos y comercialización de petroquímicos, deben sujetarse a lo previsto en el artículo Décimo Cuarto transitorio de la Ley del Sector Hidrocarburos.</p>',68,'transitorio','DACG de comercialización','Transitorios',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('58df4750-f5d6-5d72-ae9a-d9ed00867462','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Firma del acuerdo','<p> Ciudad de México, a 27 de octubre de 2026.- El Director General, Juan Carlos Solís Ávila.- Rúbrica.</p>',69,'complementario','DACG de comercialización','Acuerdo',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('5deb0b74-fd58-533e-b608-d328ceeae6d6','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Anexo I · Solicitud de otorgamiento de permiso','<p><strong>Anexo I · Solicitud de otorgamiento de permiso</strong></p><p>Formulario e instructivo publicados como imagen en el DOF. Consulta sus campos y tablas en PDF original, páginas 49 a 57. El resaltado identifica el folio impreso. Esta guía editorial no transcribe los campos del formulario.</p>',70,'anexo','Anexos de las DACG','Anexo I',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('ee7b4c39-983d-5fff-9566-c5829c4dc1d5','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Anexo II · Modificación por cesión','<p><strong>Anexo II · Modificación por cesión</strong></p><p>Formulario e instructivo publicados como imagen en el DOF. Consulta sus campos y tablas en PDF original, páginas 58 a 62. El resaltado identifica el folio impreso. Esta guía editorial no transcribe los campos del formulario.</p>',71,'anexo','Anexos de las DACG','Anexo II',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('274c7684-6e68-5a9e-b19a-7a0b69c4ff25','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Anexo III · Modificación por fusión','<p><strong>Anexo III · Modificación por fusión</strong></p><p>Formulario e instructivo publicados como imagen en el DOF. Consulta sus campos y tablas en PDF original, páginas 63 a 66. El resaltado identifica el folio impreso. Esta guía editorial no transcribe los campos del formulario.</p>',72,'anexo','Anexos de las DACG','Anexo III',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('f80f077a-51d9-5841-979c-cb65077b36db','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Anexo IV · Modificación por sucesión','<p><strong>Anexo IV · Modificación por sucesión</strong></p><p>Formulario e instructivo publicados como imagen en el DOF. Consulta sus campos y tablas en PDF original, páginas 67 a 71. El resaltado identifica el folio impreso. Esta guía editorial no transcribe los campos del formulario.</p>',73,'anexo','Anexos de las DACG','Anexo IV',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('d7db03e5-eb63-55b4-9e33-479912e89177','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Anexo V · Modificación por escisión','<p><strong>Anexo V · Modificación por escisión</strong></p><p>Formulario e instructivo publicados como imagen en el DOF. Consulta sus campos y tablas en PDF original, páginas 72 a 76. El resaltado identifica el folio impreso. Esta guía editorial no transcribe los campos del formulario.</p>',74,'anexo','Anexos de las DACG','Anexo V',NULL);
