INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('836d13d4-ef2e-55e3-a511-4409248d522d','e8aebfb8-d776-59d6-978f-623e4fb3e6af','Anexo XI · Formulario electrónico de contratos de comercialización','<p> ANEXO XI<br/> </p>
<p> FORMULARIO ELECTRÓNICO DE CONTRATOS DE COMERCIALIZACIÓN<br/> </p>
<p> El presente Anexo establece la estructura, los campos y los catálogos del Formulario de Contratos a que se refiere el Capítulo XI de las Disposiciones. El tipo de dato "Automático" indica que el Formulario de Contratos genera o precarga el dato sin captura de la persona Permisionaria de Comercialización.</p>
<p> A. Opciones del Formulario</p>
<p> El Formulario de Contratos presenta cinco opciones: Registro de contrato, Validación de contrato, Modificación de contrato, Terminación anticipada del contrato y Finalización de contrato.</p>
<p> B. Estatus del contrato </p>
<table><thead><tr> <th scope="col"> <p> Estatus </p> </th> <th scope="col"> <p> Descripción </p> </th> </tr></thead>  <tr> <td> <p> Registrado </p> </td> <td> <p> Valor que se asigna al completar un registro nuevo</p> </td> </tr> <tr> <td> <p> Aceptado </p> </td> <td> <p> La contraparte valida el contrato, cuando este se celebra entre personas Permisionarias de Comercialización. En los contratos celebrados con personas Usuarias Finales o con Permisionarias de actividades distintas a la Comercialización, el valor se asigna de forma automática al concluir el registro</p> </td> </tr> <tr> <td> <p> Rechazado </p> </td> <td> <p> La contraparte no reconoce el registro. La persona Permisionaria de Comercialización responsable del registro debe corregirlo y someterlo de nuevo a validación</p> </td> </tr> <tr> <td> <p> Finalizado </p> </td> <td> <p> Concluye la vigencia del contrato o las partes lo dan por terminado </p> </td> </tr> </table>
<p> C. Secciones y campos del registro</p>
<p> Sección 1. Datos del Comercializador </p>
<table><thead><tr> <th scope="col"> <p> Campo </p> </th> <th scope="col"> <p> Descripción </p> </th> <th scope="col"> <p> Tipo de dato </p> </th> </tr></thead>  <tr> <td> <p> Datos generales </p> </td> <td> <p> Razón social y RFC de la persona Permisionaria de Comercialización que registra</p> </td> <td> <p> Automático </p> </td> </tr> <tr> <td> <p> Permiso de la persona Permisionaria de Comercialización </p> </td> <td> <p> Número de permiso vigente</p> </td> <td> <p> Automático </p> </td> </tr> </table>
<p> Sección 2. Identificación del contrato </p>
<table><thead><tr> <th scope="col"> <p> Campo </p> </th> <th scope="col"> <p> Descripción </p> </th> <th scope="col"> <p> Tipo de dato </p> </th> </tr></thead>  <tr> <td> <p> Número de contrato </p> </td> <td> <p> Clave única del contrato</p> </td> <td> <p> Automático </p> </td> </tr> <tr> <td> <p> Fecha de firma </p> </td> <td> <p> Fecha en que se formaliza el contrato </p> </td> <td> <p> Fecha </p> </td> </tr> <tr> <td> <p> Fecha de inicio </p> </td> <td> <p> Inicio de cobertura del contrato</p> </td> <td> <p> Fecha </p> </td> </tr> <tr> <td> <p> Fecha de terminación </p> </td> <td> <p> Fin de cobertura del contrato</p> </td> <td> <p> Fecha </p> </td> </tr> <tr> <td> <p> Estatus del contrato </p> </td> <td> <p> Registrado, Aceptado, Rechazado o Finalizado </p> </td> <td> <p> Automático </p> </td> </tr> <tr> <td> <p> Relación comercial declarada en la solicitud del permiso </p> </td> <td> <p> Indica si el contrato formaliza una relación comercial declarada en la solicitud del permiso, para acreditar la relación con proveedores y clientes inicialmente declarados </p> </td> <td> <p> ○ Sí ○ No</p> </td> </tr> <tr> <td> <p> Tipo de contrato </p> </td> <td> <p> Nacional, de importación o de exportación</p> </td> <td> <p> Catálogo </p> </td> </tr> <tr> <td> <p> País </p> </td> <td> <p> País de origen o de destino, en contratos de importación o de exportación</p> </td> <td> <p> Catálogo </p> </td> </tr> </table>
<p> Sección 3. Producto y marca comercializada</p>
<table><thead><tr> <th scope="col"> <p> Campo</p> </th> <th scope="col"> <p> Descripción</p> </th> <th scope="col"> <p> Tipo de dato</p> </th> </tr></thead>  <tr> <td> <p> Producto</p> </td> <td> <p> Relación a catálogo</p> </td> <td> <p> Catálogo</p> </td> </tr> <tr> <td> <p> Subproducto</p> </td> <td> <p> Relación a catálogo</p> </td> <td> <p> Catálogo</p> </td> </tr> <tr> <td> <p> Cantidad</p> </td> <td> <p> Cantidad bajo contrato. Depende del subproducto</p> </td> <td> <p> Numérico</p> </td> </tr> <tr> <td> <p> Unidad de medida</p> </td> <td> <p> Litros, kilogramos o metros cúbicos, según el producto. Depende del subproducto</p> </td> <td> <p> Catálogo</p> </td> </tr> <tr> <td> <p> Moneda</p> </td> <td> <p> Moneda</p> </td> <td> <p> Moneda</p> </td> </tr> <tr> <td> <p> Relación a catálogo</p> </td> <td> <p> Relación a catálogo</p> </td> <td> <p> Relación a catálogo</p> </td> </tr> <tr> <td> <p> Catálogo</p> </td> <td> <p> Catálogo</p> </td> <td> <p> Catálogo</p> </td> </tr> <tr> <td> <p> Marca comercializada</p> </td> <td> <p> Marca comercial del subproducto registrada ante la Comisión. Aplica a Petrolíferos, con excepción del Gas Licuado de Petróleo. Depende del subproducto</p> </td> <td> <p> Catálogo</p> </td> </tr> <tr> <td> <p> Origen de la marca</p> </td> <td> <p> Producción, Importación o según lo estipulado en el contrato. Permite identificar en qué eslabón de la cadena de suministro se generó o modificó el producto. Depende del subproducto</p> </td> <td> <p> Catálogo</p> </td> </tr> <tr> <td> <p> Señala el país de origen de la Marca, en caso de Importación</p> </td> <td> <p> Señala el país de origen de la Marca, en caso de Importación</p> </td> <td> <p> Señala el país de origen de la Marca, en caso de Importación</p> </td> </tr> </table>
<p> Cuando el contrato incluya más de un producto, se agrega un registro por cada uno.</p>
<p> Sección 4. Relación comercial</p>
<table><thead><tr> <th scope="col"> <p> Campo</p> </th> <th scope="col"> <p> Descripción</p> </th> <th scope="col"> <p> Tipo de dato</p> </th> </tr></thead>  <tr> <td> <p> Rol de la persona Permisionaria de Comercialización</p> </td> <td> <p> Comprador o Vendedor</p> </td> <td> <p> Catálogo</p> </td> </tr> <tr> <td> <p> La contraparte es persona Permisionaria de Comercialización de la Comisión</p> </td> <td> <p> ○ Sí     ○ No</p> </td> <td> <p> Casilla</p> </td> </tr> <tr> <td> <p> Permiso de la contraparte</p> </td> <td> <p> Número de permiso vigente de la contraparte, cuando aplique</p> </td> <td> <p> Catálogo</p> </td> </tr> <tr> <td> <p> Razón social de la contraparte</p> </td> <td> <p> Se despliega de forma automática cuando la contraparte es persona Permisionaria de Comercialización; en caso contrario, se captura</p> </td> <td> <p> Automático o texto</p> </td> </tr> <tr> <td> <p> RFC de la contraparte</p> </td> <td> <p> Se despliega de forma automática cuando la contraparte es persona Permisionaria de Comercialización; en caso contrario, se captura</p> </td> <td> <p> Automático o texto</p> </td> </tr> </table>
<p> Sección 5. Logística asociada (cuando resulte aplicable)</p>
<table><thead><tr> <th scope="col"> <p> Campo</p> </th> <th scope="col"> <p> Descripción</p> </th> <th scope="col"> <p> Tipo de dato</p> </th> </tr></thead>  <tr> <td> <p> Servicios incluidos</p> </td> <td> <p> Transporte, Almacenamiento o Distribución, gestión logística, compresión, descompresión, licuefacción o regasificación de Gas Natural, o servicio de valor agregado (con descripción)</p> </td> <td> <p> Catálogo</p> </td> </tr> <tr> <td> <p> Permiso asociado</p> </td> <td> <p> Número de permiso del servicio, cuando aplique</p> </td> <td> <p> Catálogo</p> </td> </tr> <tr> <td> <p> Instalación de entrega y recepción</p> </td> <td> <p> Terminal de Almacenamiento o planta de Distribución</p> </td> <td> <p> Catálogo</p> </td> </tr> <tr> <td> <p> Demanda proyectada</p> </td> <td> <p> Volumen demandado proyectado para el semestre siguiente, en la unidad de medida del producto</p> </td> <td> <p> Numérico</p> </td> </tr> <tr> <td colspan="3"> <p> Almacenamiento</p> </td> </tr> <tr> <td> <p> Volumen de reserva</p> </td> <td> <p> Volumen de reserva de capacidad</p> </td> <td> <p> Numérico</p> </td> </tr> <tr> <td> <p> Tipo de reserva por producto</p> </td> <td> <p> Contractual, de uso común, base firme o base interrumpible</p> </td> <td> <p> Catálogo</p> </td> </tr> <tr> <td colspan="3"> <p> Transporte</p> </td> </tr> <tr> <td> <p> Medio de transporte</p> </td> <td> <p> Auto-tanque, carro-tanque, por medio de Ductos o buque-tanque</p> </td> <td> <p> Catálogo</p> </td> </tr> <tr> <td> <p> Origen o recepción</p> </td> <td> <p> Ubicación física</p> </td> <td> <p> Catálogo</p> </td> </tr> <tr> <td> <p> Destino o depósito</p> </td> <td> <p> Ubicación física</p> </td> <td> <p> Catálogo</p> </td> </tr> <tr> <td colspan="3"> <p> Distribución </p> </td> </tr> <tr> <td> <p> Origen o recepción</p> </td> <td> <p> Ubicación física</p> </td> <td> <p> Catálogo</p> </td> </tr> <tr> <td> <p> Destino o depósito</p> </td> <td> <p> Ubicación física</p> </td> <td> <p> Catálogo</p> </td> </tr> </table>
<p> Sección 6. Declaración de Trazabilidad</p>
<table><thead><tr> <th scope="col"> <p> Campo</p> </th> <th scope="col"> <p> Descripción</p> </th> <th scope="col"> <p> Tipo de dato</p> </th> </tr></thead>  <tr> <td> <p> ContratoId</p> </td> <td> <p> Identificador único que se genera al completarse el registro. Se remite a la contraparte para su validación y se declara en cada transacción derivada del contrato</p> </td> <td> <p> Automático</p> </td> </tr> </table>
<p> Sección 7. Archivos adjuntos</p>
<table><thead><tr> <th scope="col"> <p> Campo</p> </th> <th scope="col"> <p> Descripción</p> </th> <th scope="col"> <p> Tipo de dato</p> </th> </tr></thead>  <tr> <td> <p> Contrato</p> </td> <td> <p> Contrato digitalizado con sus anexos</p> </td> <td> <p> PDF</p> </td> </tr> </table>
<p> Sección 8. Resolución de validez (contraparte)</p>
<table><thead><tr> <th scope="col"> <p> Campo</p> </th> <th scope="col"> <p> Descripción</p> </th> <th scope="col"> <p> Tipo de dato</p> </th> </tr></thead>  <tr> <td> <p> Resolución</p> </td> <td> <p> Aceptar o rechazar el registro realizado por la persona Permisionaria de Comercialización responsable</p> </td> <td> <p> Catálogo</p> </td> </tr> </table>
<p> D. Modificación del contrato</p>
<table><thead><tr> <th scope="col"> <p> Campo</p> </th> <th scope="col"> <p> Descripción</p> </th> <th scope="col"> <p> Tipo de dato</p> </th> </tr></thead>  <tr> <td> <p> Causas de la modificación</p> </td> <td> <p> Descripción detallada de la razón de la modificación del contrato</p> </td> <td> <p> Texto</p> </td> </tr> <tr> <td> <p> Comprobante</p> </td> <td> <p> Documento que acredite el cambio</p> </td> <td> <p> PDF</p> </td> </tr> </table>
<p> Nota: La modificación permite actualizar: las fechas, la relación comercial declarada y el tipo de contrato, el producto, la marca y el origen de la marca, así como incorporar nuevos productos, el rol de la persona Permisionaria de Comercialización, la logística asociada, y el contrato y sus anexos.</p>
<p> E. Terminación anticipada del contrato</p>
<table><thead><tr> <th scope="col"> <p> Campo</p> </th> <th scope="col"> <p> Descripción</p> </th> <th scope="col"> <p> Tipo de dato</p> </th> </tr></thead>  <tr> <td> <p> Causas de la terminación anticipada</p> </td> <td> <p> Ejecución total de las obligaciones derivadas del contrato; fallecimiento de la persona física contratante; mutuo consentimiento; incumplimiento de las obligaciones de alguna de las partes; otra (especificar)</p> </td> <td> <p> Catálogo</p> </td> </tr> <tr> <td> <p> Fecha de terminación anticipada</p> </td> <td> <p> Fecha en que concluye el contrato (dd/mm/aaaa)</p> </td> <td> <p> Fecha</p> </td> </tr> <tr> <td> <p> Comprobante</p> </td> <td> <p> Documento que acredite la terminación</p> </td> <td> <p> PDF</p> </td> </tr> </table>
<p> F. Finalización del contrato</p>
<table><thead><tr> <th scope="col"> <p> Campo</p> </th> <th scope="col"> <p> Descripción</p> </th> <th scope="col"> <p> Tipo de dato</p> </th> </tr></thead>  <tr> <td> <p> Manifestación </p> </td> <td> <p> Manifiesto bajo protesta de decir verdad que el contrato registrado ya ha finalizado y su vigencia no fue ampliada</p> </td> <td> <p> ○ Sí ○ No</p> </td> </tr> <tr> <td> <p> Fecha de finalización</p> </td> <td> <p> Fecha en que concluye el contrato (dd/mm/aaaa).</p> </td> <td> <p> Fecha </p> </td> </tr> </table>
<p> _______________________________<br/> </p>',80,'anexo','DACG de comercialización','Anexo XI',NULL);
